window.CFA_LESSONS=(window.CFA_LESSONS||[]).concat([{"module_id":"CFA26-10-03","title":"Guidance for Standards I–VII","version":"2026","source_basis":[{"source_id":"CFAI_2026","pdf_pages":[67,254],"relation":"primary"},{"source_id":"Kaplan_2026","pdf_pages":[167,194],"relation":"supplementary"},{"source_id":"SAPP_2026","pdf_pages":[23,200],"relation":"supplementary"}],"los_coverage":[{"los_id":"CFA26-10-03-LOS01","learning_goal_vi":"Áp dụng Code và Standards vào tình huống về professional integrity.","status":"targeted_CFAI_Kaplan_SAPP_scenarios_QA_pass","competency_criteria":["Mọi Standard I–VII hoặc GIPS topics cần có nội dung liên quan","Phân tích facts, exception, compliance controls và cách nhận biết hành vi sai","2+ original cases và 3+ câu trắc nghiệm có lời giải, được kiểm tra theo nguồn phù hợp"],"concept_ids":["S01-01","S01-02","S01-03","S01-04","S01-05","S01-06","S01-07","S01-08","S01-09","S01-10","S01-11","S01-12","S01-13","S01-14","S01-15","S01-16","S01-17","S01-18","S01-19","S01-20","S01-21","S01-22","S01-23"],"formula_ids":["F01-01"],"example_ids":["E01-01","E01-02"],"question_ids":["Q01-01","Q01-02","Q01-03","Q01-04","Q01-05","Q01-06","Q01-07","Q01-08","Q01-09","Q01-10","Q01-11","Q01-12","Q01-13","Q01-14","Q01-15","Q01-16","Q01-17","Q01-18","Q01-19","Q01-20","Q01-21","Q01-22","Q01-23"],"source_anchor_pages":{"CFAI_2026":{"file":"2026_CFA_L1V10_Ethics_ONLINE.pdf","pdf_page":67},"Kaplan_2026":{"file":"Kaplan SchweserNotes Book4.pdf","pdf_page":167},"SAPP_2026":{"file":"SAPP Ethics.pdf","pdf_page":24}},"missing_items":[]},{"los_id":"CFA26-10-03-LOS02","learning_goal_vi":"Đề xuất practices và procedures được thiết kế nhằm phòng ngừa violations.","status":"targeted_CFAI_Kaplan_SAPP_scenarios_QA_pass","competency_criteria":["Mọi Standard I–VII hoặc GIPS topics cần có nội dung liên quan","Phân tích facts, exception, compliance controls và cách nhận biết hành vi sai","2+ original cases và 3+ câu trắc nghiệm có lời giải, được kiểm tra theo nguồn phù hợp"],"concept_ids":["S02-01","S02-02","S02-03","S02-04","S02-05","S02-06","S02-07","S02-08","S02-09","S02-10","S02-11","S02-12","S02-13","S02-14","S02-15","S02-16","S02-17","S02-18","S02-19","S02-20","S02-21","S02-22","S02-23","S02-24"],"formula_ids":["F02-01"],"example_ids":["E02-01","E02-02"],"question_ids":["Q02-01","Q02-02","Q02-03"],"source_anchor_pages":{"CFAI_2026":{"file":"2026_CFA_L1V10_Ethics_ONLINE.pdf","pdf_page":115},"Kaplan_2026":{"file":"Kaplan SchweserNotes Book4.pdf","pdf_page":167},"SAPP_2026":{"file":"SAPP Ethics.pdf","pdf_page":90}},"missing_items":[]},{"los_id":"CFA26-10-03-LOS03","learning_goal_vi":"Xác định hành vi phù hợp và vi phạm Code/Standards theo facts.","status":"targeted_CFAI_Kaplan_SAPP_scenarios_QA_pass","competency_criteria":["Mọi Standard I–VII hoặc GIPS topics cần có nội dung liên quan","Phân tích facts, exception, compliance controls và cách nhận biết hành vi sai","2+ original cases và 3+ câu trắc nghiệm có lời giải, được kiểm tra theo nguồn phù hợp"],"concept_ids":["S03-01","S03-02","S03-03","S03-04","S03-05","S03-06","S03-07","S03-08","S03-09","S03-10","S03-11","S03-12","S03-13","S03-14","S03-15","S03-16","S03-17","S03-18","S03-19","S03-20","S03-21","S03-22","S03-23","S03-24"],"formula_ids":["F03-01"],"example_ids":["E03-01","E03-02"],"question_ids":["Q03-01","Q03-02","Q03-03","Q03-04","Q03-05","Q03-06","Q03-07","Q03-08","Q03-09","Q03-10","Q03-11","Q03-12","Q03-13","Q03-14","Q03-15","Q03-16","Q03-17","Q03-18","Q03-19","Q03-20","Q03-21","Q03-22","Q03-23"],"source_anchor_pages":{"CFAI_2026":{"file":"2026_CFA_L1V10_Ethics_ONLINE.pdf","pdf_page":196},"Kaplan_2026":{"file":"Kaplan SchweserNotes Book4.pdf","pdf_page":167},"SAPP_2026":{"file":"SAPP Ethics.pdf","pdf_page":170}},"missing_items":[]}],"sections":[{"id":"S01-01","los_ids":["CFA26-10-03-LOS01"],"heading_vi":"I(A) Knowledge of the Law: nội dung và phạm vi","body_vi":"Khi làm việc ở nhiều jurisdiction, phải xác định applicable laws/rules, CFA Code/Standards và áp dụng mức nghiêm ngặt hơn khi có khác biệt. Không được knowingly assist violation; phải dissociate khỏi hành vi sai. Để phân loại tình huống phải xác định quan hệ giữa analyst/manager, client, employer, thông tin công khai và thực chất hành vi. Ví dụ rủi ro: Researcher được yêu cầu bán một tài sản bị cấm theo quy định sở tại dù Code không nhắc đến sản phẩm đó. Cách xử lý phù hợp: Từ chối thực hiện, báo compliance, lưu quyết định, theo quy định pháp luật nghiêm ngặt hơn."},{"id":"S01-02","los_ids":["CFA26-10-03-LOS01"],"heading_vi":"I(B) Independence and Objectivity: nội dung và phạm vi","body_vi":"Giữ independent professional judgment trước quà tặng, hospitality, travel, investment-banking pressure hay bên bán nghiên cứu. Giá trị quà có thể ảnh hưởng tính khách quan; disclosure không luôn chữa được ảnh hưởng thực chất. Để phân loại tình huống phải xác định quan hệ giữa analyst/manager, client, employer, thông tin công khai và thực chất hành vi. Ví dụ rủi ro: Issuer trả toàn bộ kỳ nghỉ cao cấp để analyst đưa ra khuyến nghị mua, analyst chấp nhận và hứa nâng rating. Cách xử lý phù hợp: Từ chối hoặc xử lý theo chính sách independent research; để công ty kiểm soát gifts và phân tách bộ phận investment banking."},{"id":"S01-03","los_ids":["CFA26-10-03-LOS01"],"heading_vi":"I(C) Misrepresentation: nội dung và phạm vi","body_vi":"Không cố tình trình bày sai phương pháp, credentials, track record, forecast là fact, hoặc dùng tài liệu của người khác không ghi nguồn. Không dùng charts chọn kỳ thuận lợi để tạo ấn tượng sai lệch. Để phân loại tình huống phải xác định quan hệ giữa analyst/manager, client, employer, thông tin công khai và thực chất hành vi. Ví dụ rủi ro: Advisor tự nhận đã tạo model của đồng nghiệp và ghi “bảo đảm lợi nhuận 15% mỗi năm”. Cách xử lý phù hợp: Ghi nguồn rõ ràng, công bố assumptions, nhấn mạnh forecast không phải cam kết và xác minh dữ liệu."},{"id":"S01-04","los_ids":["CFA26-10-03-LOS01"],"heading_vi":"I(D) Misconduct: nội dung và phạm vi","body_vi":"Cấm hành vi nghề nghiệp dishonesty, fraud, deceit hoặc hành vi phản ánh bất lợi tới reputation, integrity và competence. Không phải mọi vi phạm luật riêng tư đều tự động là professional misconduct, cần xét tính liên quan và facts. Để phân loại tình huống phải xác định quan hệ giữa analyst/manager, client, employer, thông tin công khai và thực chất hành vi. Ví dụ rủi ro: Portfolio manager sửa hóa đơn để nhận khoản hoàn trả chi phí không phát sinh. Cách xử lý phù hợp: Không gian lận expense records, báo nội bộ khi cần và chịu trách nhiệm sửa sai."},{"id":"S01-05","los_ids":["CFA26-10-03-LOS01"],"heading_vi":"I(E) Competence: nội dung và phạm vi","body_vi":"Phải có và duy trì năng lực thực tế cần thiết cho nhiệm vụ chuyên môn; không nhất thiết có một số giờ continuing education cố định cho mọi công việc. Khi chuyển sản phẩm phức tạp phải học hoặc tìm chuyên gia. Để phân loại tình huống phải xác định quan hệ giữa analyst/manager, client, employer, thông tin công khai và thực chất hành vi. Ví dụ rủi ro: Analyst không hiểu cấu trúc path-dependent options nhưng vẫn công bố valuation “đã xác minh”. Cách xử lý phù hợp: Học/tham vấn chuyên môn, kiểm định pricing và nói rõ hạn chế trước khi khuyến nghị."},{"id":"S01-06","los_ids":["CFA26-10-03-LOS01"],"heading_vi":"II(A) Material Nonpublic Information: nội dung và phạm vi","body_vi":"Người nắm material nonpublic information có thể ảnh hưởng giá đầu tư không được trading hoặc khiến người khác trading trên thông tin đó. Mosaic theory cho phép public plus nonmaterial nonpublic info được phân tích hợp pháp. Để phân loại tình huống phải xác định quan hệ giữa analyst/manager, client, employer, thông tin công khai và thực chất hành vi. Ví dụ rủi ro: Analyst biết kết quả sáp nhập bí mật từ CFO và mua cổ phiếu trước thông báo. Cách xử lý phù hợp: Không giao dịch/gợi ý người khác; báo compliance, restricted list và chờ thông tin public được phổ biến."},{"id":"S01-07","los_ids":["CFA26-10-03-LOS01"],"heading_vi":"II(B) Market Manipulation: nội dung và phạm vi","body_vi":"Cấm hành vi bóp méo prices hoặc làm tăng volume giả tạo với intent gây hiểu nhầm. Giao dịch hợp pháp dựa trên phân tích thực khác với spoofing, wash trades hoặc tin giả nhằm thao túng. Để phân loại tình huống phải xác định quan hệ giữa analyst/manager, client, employer, thông tin công khai và thực chất hành vi. Ví dụ rủi ro: Trader đặt lệnh ảo lớn để tạo cảm giác demand cao rồi hủy trước khi khớp. Cách xử lý phù hợp: Giao dịch phản ánh nhu cầu thực và thông tin trung thực, không tạo tín hiệu order book giả."},{"id":"S01-08","los_ids":["CFA26-10-03-LOS01"],"heading_vi":"III(A) Loyalty, Prudence, and Care: nội dung và phạm vi","body_vi":"Trong nhiệm vụ với khách hàng, đặt lợi ích clients lên trước employer và bản thân; xử lý tài sản được ủy thác cẩn trọng, không làm lợi công ty bằng fees không minh bạch hoặc giao dịch bất lợi. Để phân loại tình huống phải xác định quan hệ giữa analyst/manager, client, employer, thông tin công khai và thực chất hành vi. Ví dụ rủi ro: Manager chọn broker phí cao có liên quan cá nhân dù execution quality kém. Cách xử lý phù hợp: Đánh giá execution net of costs cho khách hàng, không ưu tiên affiliate nếu bất lợi."},{"id":"S01-09","los_ids":["CFA26-10-03-LOS01"],"heading_vi":"III(B) Fair Dealing: nội dung và phạm vi","body_vi":"Đối xử fair, objective với tất cả clients về research, recommendations và trade actions; fair không bắt buộc identical timing tuyệt đối, nhưng không cố ý thiên vị một nhóm vì phí cao. Để phân loại tình huống phải xác định quan hệ giữa analyst/manager, client, employer, thông tin công khai và thực chất hành vi. Ví dụ rủi ro: Analyst gửi khuyến nghị mới cho nhóm bạn bè một ngày trước các khách hàng khác cùng loại dịch vụ. Cách xử lý phù hợp: Thiết lập phân phối đồng thời, trade allocation công bằng và có hồ sơ lý do nếu hạn chế thanh khoản."},{"id":"S01-10","los_ids":["CFA26-10-03-LOS01"],"heading_vi":"III(C) Suitability: nội dung và phạm vi","body_vi":"Trong advisory relationship phải cập nhật objectives, risk/return profile, financial constraints và xem suitability trong context tổng portfolio. Khi quản lý mandate cụ thể, chỉ hành động phù hợp mandate đã công bố. Để phân loại tình huống phải xác định quan hệ giữa analyst/manager, client, employer, thông tin công khai và thực chất hành vi. Ví dụ rủi ro: Advisor đặt 60% vốn hưu trí cho khách sắp nghỉ vào tài sản leveraged illiquid dù cần rút tiền năm tới. Cách xử lý phù hợp: Thu thập liquidity horizon/risk tolerance, đánh giá portfolio-level concentration, chỉ khuyến nghị phù hợp."},{"id":"S01-11","los_ids":["CFA26-10-03-LOS01"],"heading_vi":"III(D) Performance Presentation: nội dung và phạm vi","body_vi":"Trình bày kết quả fair, accurate, complete; không dùng selective periods, loại losing accounts hay số gross/net không rõ để đánh lừa. Có thể dùng composites phù hợp, disclosed methodology. Để phân loại tình huống phải xác định quan hệ giữa analyst/manager, client, employer, thông tin công khai và thực chất hành vi. Ví dụ rủi ro: Manager giới thiệu “5 năm lợi nhuận cao” nhưng chỉ chọn tài khoản thắng lớn, bỏ tất cả tài khoản lỗ. Cách xử lý phù hợp: Công bố phương pháp, time windows nhất quán, nêu limitations và số liệu đầy đủ, rõ gross/net."},{"id":"S01-12","los_ids":["CFA26-10-03-LOS01"],"heading_vi":"III(E) Preservation of Confidentiality: nội dung và phạm vi","body_vi":"Bảo mật thông tin current, former và prospective clients; exceptions: client illegal activities, disclosure required by law, hoặc client permission. Không tự chia sẻ tên khách cho marketing bên thứ ba. Để phân loại tình huống phải xác định quan hệ giữa analyst/manager, client, employer, thông tin công khai và thực chất hành vi. Ví dụ rủi ro: Advisor chuyển danh sách khách VIP cho người quen làm bảo hiểm dù chưa có đồng ý. Cách xử lý phù hợp: Chỉ chia sẻ trong phạm vi được phép hoặc theo legal requirement, bảo vệ file và access."},{"id":"S01-13","los_ids":["CFA26-10-03-LOS01"],"heading_vi":"IV(A) Loyalty: nội dung và phạm vi","body_vi":"Không gây hại employer trong professional activities, không tiết lộ bí mật hoặc lấy cắp sản phẩm nghiên cứu; việc chuẩn bị mở doanh nghiệp sau khi nghỉ cần phân biệt với cạnh tranh gây hại khi còn làm. Để phân loại tình huống phải xác định quan hệ giữa analyst/manager, client, employer, thông tin công khai và thực chất hành vi. Ví dụ rủi ro: Employee tải về toàn bộ client list mật rồi chuyển sang competitor trước ngày nghỉ. Cách xử lý phù hợp: Giữ bí mật, tuân hợp đồng, chỉ dùng thông tin public/mối quan hệ hợp pháp sau nghỉ."},{"id":"S01-14","los_ids":["CFA26-10-03-LOS01"],"heading_vi":"IV(B) Additional Compensation Arrangements: nội dung và phạm vi","body_vi":"Nếu nhận benefit/compensation có thể compete hoặc conflict với lợi ích employer, cần **written consent từ tất cả bên liên quan** trước. Không đủ khi chỉ thông báo bằng miệng hay lấy phép khách hàng đơn phương. Để phân loại tình huống phải xác định quan hệ giữa analyst/manager, client, employer, thông tin công khai và thực chất hành vi. Ví dụ rủi ro: Manager nhận bonus riêng từ client nếu vượt index nhưng không xin phép employer. Cách xử lý phù hợp: Xin written consent từ employer và bên liên quan trước khi chấp nhận arrangement."},{"id":"S01-15","los_ids":["CFA26-10-03-LOS01"],"heading_vi":"IV(C) Responsibilities of Supervisors: nội dung và phạm vi","body_vi":"Supervisors phải có reasonable efforts để người dưới quyền tuân luật, regulations và Code/Standards, gồm effective compliance programs; giao toàn bộ trách nhiệm cho bộ phận khác không loại nghĩa vụ. Để phân loại tình huống phải xác định quan hệ giữa analyst/manager, client, employer, thông tin công khai và thực chất hành vi. Ví dụ rủi ro: Team leader biết research analysts bị pressure viết báo cáo giả nhưng không thiết lập review hay xử lý. Cách xử lý phù hợp: Triển khai procedures phát hiện/phòng vi phạm, audit và hành động sửa khi có red flags."},{"id":"S01-16","los_ids":["CFA26-10-03-LOS01"],"heading_vi":"V(A) Diligence and Reasonable Basis: nội dung và phạm vi","body_vi":"Research và recommendation cần thorough independent analysis với adequate basis; dùng third-party research phải đánh giá chất lượng methodology/data. Tin đồn không đủ làm cơ sở buy/sell. Để phân loại tình huống phải xác định quan hệ giữa analyst/manager, client, employer, thông tin công khai và thực chất hành vi. Ví dụ rủi ro: Analyst upgrade stock vì một bài đăng ẩn danh không kiểm chứng trên mạng xã hội. Cách xử lý phù hợp: Kiểm tra data, model assumptions, issuer information, downside risk và evidence phù hợp."},{"id":"S01-17","los_ids":["CFA26-10-03-LOS01"],"heading_vi":"V(B) Communication with Clients and Prospective Clients: nội dung và phạm vi","body_vi":"Phải disclose nature of services cùng related costs, methodology và material changes, important investment factors, significant limitations/risks, phân biệt facts và opinions. Không trình bày scenario như certainty. Để phân loại tình huống phải xác định quan hệ giữa analyst/manager, client, employer, thông tin công khai và thực chất hành vi. Ví dụ rủi ro: Adviser bán strategy phí cao nhưng che management/exit fees và cam kết return dự phóng như thực tế. Cách xử lý phù hợp: Trình bày phí rõ, risks, assumptions, model uncertainties và material changes cho client."},{"id":"S01-18","los_ids":["CFA26-10-03-LOS01"],"heading_vi":"V(C) Record Retention: nội dung và phạm vi","body_vi":"Tạo và duy trì records thích hợp cho investment analysis, recommendations và client communications. Thời hạn theo luật, regulation và firm policy; nếu thiếu, tham khảo guidance tương ứng và yêu cầu phù hợp. Để phân loại tình huống phải xác định quan hệ giữa analyst/manager, client, employer, thông tin công khai và thực chất hành vi. Ví dụ rủi ro: Analyst xóa toàn bộ supporting model sau khi khách hàng đầu tư, không thể chứng minh thesis. Cách xử lý phù hợp: Lưu data/model và versions đủ tái lập rationale; bàn giao records theo chính sách employer."},{"id":"S01-19","los_ids":["CFA26-10-03-LOS01"],"heading_vi":"VI(A) Avoid or Disclose Conflicts: nội dung và phạm vi","body_vi":"Ưu tiên avoid conflicts, nếu không thể tránh phải full and fair disclosure rõ ràng, nổi bật và dễ hiểu tới các bên liên quan; disclaimer mơ hồ ở cuối tài liệu chưa đủ. Một số conflicts cần từ chối hành động. Để phân loại tình huống phải xác định quan hệ giữa analyst/manager, client, employer, thông tin công khai và thực chất hành vi. Ví dụ rủi ro: Analyst sở hữu lượng lớn cổ phiếu đang khuyến nghị mua mà chỉ ghi “có thể có lợi ích”. Cách xử lý phù hợp: Avoid coverage nếu ảnh hưởng objectivity, hoặc disclose cụ thể holdings và implications rõ ràng."},{"id":"S01-20","los_ids":["CFA26-10-03-LOS01"],"heading_vi":"VI(B) Priority of Transactions: nội dung và phạm vi","body_vi":"Giao dịch cho clients và employer phải ưu tiên trước personal beneficial ownership của member/candidate; không giao dịch trước clients để hưởng biến động do client order. Để phân loại tình huống phải xác định quan hệ giữa analyst/manager, client, employer, thông tin công khai và thực chất hành vi. Ví dụ rủi ro: Trader mua trước cho tài khoản cá nhân ngay khi biết lệnh mua lớn của client sẽ được thực hiện. Cách xử lý phù hợp: Thực hiện client/employer transactions trước, tuân personal dealing restrictions."},{"id":"S01-21","los_ids":["CFA26-10-03-LOS01"],"heading_vi":"VI(C) Referral Fees: nội dung và phạm vi","body_vi":"Disclosure cho employer, clients và prospective clients (as appropriate) về mọi lợi ích/fee nhận hoặc trả khi giới thiệu product/services, kể cả incentive noncash. Để phân loại tình huống phải xác định quan hệ giữa analyst/manager, client, employer, thông tin công khai và thực chất hành vi. Ví dụ rủi ro: Advisor giới thiệu một manager và nhận 1% assets mà không disclosure cho khách. Cách xử lý phù hợp: Nêu rõ bản chất và mức/ước lượng khoản referral compensation trước khi client quyết định."},{"id":"S01-22","los_ids":["CFA26-10-03-LOS01"],"heading_vi":"VII(A) Conduct as Participants in CFA Institute Programs: nội dung và phạm vi","body_vi":"Không hành xử làm ảnh hưởng integrity/reputation/security của CFA exams/programs; việc tiết lộ câu hỏi/nội dung cụ thể thuộc confidential exam information là violation, kể cả sau khi đã thi. Để phân loại tình huống phải xác định quan hệ giữa analyst/manager, client, employer, thông tin công khai và thực chất hành vi. Ví dụ rủi ro: Candidate đăng các câu và đáp án cụ thể vừa gặp ở exam lên nhóm chat. Cách xử lý phù hợp: Giữ bí mật exam content; có thể nêu nhận xét chung về trải nghiệm mà không tiết lộ nội dung bảo mật."},{"id":"S01-23","los_ids":["CFA26-10-03-LOS01"],"heading_vi":"VII(B) Reference to CFA Institute, CFA Designation, and CFA Program: nội dung và phạm vi","body_vi":"Không exaggerate ý nghĩa qualification/membership/candidacy, không hàm ý CFA Institute bảo đảm kết quả hoặc cấp mức Level I như designation. Dùng cách ghi trung thực về trạng thái đang học và kỳ thi đã qua. Để phân loại tình huống phải xác định quan hệ giữa analyst/manager, client, employer, thông tin công khai và thực chất hành vi. Ví dụ rủi ro: Candidate ghi “CFA Level I certified expert, CFA guarantees 20% annual returns”. Cách xử lý phù hợp: Ghi đúng “passed Level I of CFA Program” khi thực sự qua, tránh claims performance guarantees."},{"id":"S02-01","los_ids":["CFA26-10-03-LOS02"],"heading_vi":"I(A) — thiết kế kiểm soát phòng ngừa","body_vi":"Đối với I(A) Knowledge of the Law, hệ thống kiểm soát phải đi từ nhận diện nguồn rủi ro đến hành động khắc phục và lưu dấu vết: Duy trì bảng cập nhật luật cho sản phẩm/jurisdiction; cơ chế hỏi legal counsel và báo cáo/dissociate khi phát hiện vi phạm. Một quy trình chỉ hiệu quả khi người chịu trách nhiệm, thời điểm kiểm tra và cơ chế escalation được xác định rõ, không chỉ ghi “tuân thủ quy định” chung chung."},{"id":"S02-02","los_ids":["CFA26-10-03-LOS02"],"heading_vi":"I(B) — thiết kế kiểm soát phòng ngừa","body_vi":"Đối với I(B) Independence and Objectivity, hệ thống kiểm soát phải đi từ nhận diện nguồn rủi ro đến hành động khắc phục và lưu dấu vết: Đặt ngưỡng quà tặng, approval, trả tiền di chuyển/khách sạn, firewall giữa research và transaction banking. Một quy trình chỉ hiệu quả khi người chịu trách nhiệm, thời điểm kiểm tra và cơ chế escalation được xác định rõ, không chỉ ghi “tuân thủ quy định” chung chung."},{"id":"S02-03","los_ids":["CFA26-10-03-LOS02"],"heading_vi":"I(C) — thiết kế kiểm soát phòng ngừa","body_vi":"Đối với I(C) Misrepresentation, hệ thống kiểm soát phải đi từ nhận diện nguồn rủi ro đến hành động khắc phục và lưu dấu vết: Checklist marketing/research, kiểm duyệt claim, lưu source citations và version controls. Một quy trình chỉ hiệu quả khi người chịu trách nhiệm, thời điểm kiểm tra và cơ chế escalation được xác định rõ, không chỉ ghi “tuân thủ quy định” chung chung."},{"id":"S02-04","los_ids":["CFA26-10-03-LOS02"],"heading_vi":"I(D) — thiết kế kiểm soát phòng ngừa","body_vi":"Đối với I(D) Misconduct, hệ thống kiểm soát phải đi từ nhận diện nguồn rủi ro đến hành động khắc phục và lưu dấu vết: Segregation of duties, fraud reporting, review expense, escalation channels không trả đũa. Một quy trình chỉ hiệu quả khi người chịu trách nhiệm, thời điểm kiểm tra và cơ chế escalation được xác định rõ, không chỉ ghi “tuân thủ quy định” chung chung."},{"id":"S02-05","los_ids":["CFA26-10-03-LOS02"],"heading_vi":"I(E) — thiết kế kiểm soát phòng ngừa","body_vi":"Đối với I(E) Competence, hệ thống kiểm soát phải đi từ nhận diện nguồn rủi ro đến hành động khắc phục và lưu dấu vết: Competency matrix theo vai trò, cập nhật năng lực thường xuyên, peer review models và đào tạo khi mở sản phẩm mới. Một quy trình chỉ hiệu quả khi người chịu trách nhiệm, thời điểm kiểm tra và cơ chế escalation được xác định rõ, không chỉ ghi “tuân thủ quy định” chung chung."},{"id":"S02-06","los_ids":["CFA26-10-03-LOS02"],"heading_vi":"II(A) — thiết kế kiểm soát phòng ngừa","body_vi":"Đối với II(A) Material Nonpublic Information, hệ thống kiểm soát phải đi từ nhận diện nguồn rủi ro đến hành động khắc phục và lưu dấu vết: Information barriers, restricted/watch lists, pre-clearance, confidentiality training và monitoring. Một quy trình chỉ hiệu quả khi người chịu trách nhiệm, thời điểm kiểm tra và cơ chế escalation được xác định rõ, không chỉ ghi “tuân thủ quy định” chung chung."},{"id":"S02-07","los_ids":["CFA26-10-03-LOS02"],"heading_vi":"II(B) — thiết kế kiểm soát phòng ngừa","body_vi":"Đối với II(B) Market Manipulation, hệ thống kiểm soát phải đi từ nhận diện nguồn rủi ro đến hành động khắc phục và lưu dấu vết: Trade surveillance, cấm spoofing/wash trading, review social-media market communication. Một quy trình chỉ hiệu quả khi người chịu trách nhiệm, thời điểm kiểm tra và cơ chế escalation được xác định rõ, không chỉ ghi “tuân thủ quy định” chung chung."},{"id":"S02-08","los_ids":["CFA26-10-03-LOS02"],"heading_vi":"III(A) — thiết kế kiểm soát phòng ngừa","body_vi":"Đối với III(A) Loyalty, Prudence, and Care, hệ thống kiểm soát phải đi từ nhận diện nguồn rủi ro đến hành động khắc phục và lưu dấu vết: Best execution policies, conflict registry, kiểm tra fees/commissions, independent investment committee. Một quy trình chỉ hiệu quả khi người chịu trách nhiệm, thời điểm kiểm tra và cơ chế escalation được xác định rõ, không chỉ ghi “tuân thủ quy định” chung chung."},{"id":"S02-09","los_ids":["CFA26-10-03-LOS02"],"heading_vi":"III(B) — thiết kế kiểm soát phòng ngừa","body_vi":"Đối với III(B) Fair Dealing, hệ thống kiểm soát phải đi từ nhận diện nguồn rủi ro đến hành động khắc phục và lưu dấu vết: Pre-determined trade allocation policies, distribution lists, communication controls và periodic allocation audit. Một quy trình chỉ hiệu quả khi người chịu trách nhiệm, thời điểm kiểm tra và cơ chế escalation được xác định rõ, không chỉ ghi “tuân thủ quy định” chung chung."},{"id":"S02-10","los_ids":["CFA26-10-03-LOS02"],"heading_vi":"III(C) — thiết kế kiểm soát phòng ngừa","body_vi":"Đối với III(C) Suitability, hệ thống kiểm soát phải đi từ nhận diện nguồn rủi ro đến hành động khắc phục và lưu dấu vết: Periodic IPS refresh, suitability forms, limits/concentration alerts và exceptions approval. Một quy trình chỉ hiệu quả khi người chịu trách nhiệm, thời điểm kiểm tra và cơ chế escalation được xác định rõ, không chỉ ghi “tuân thủ quy định” chung chung."},{"id":"S02-11","los_ids":["CFA26-10-03-LOS02"],"heading_vi":"III(D) — thiết kế kiểm soát phòng ngừa","body_vi":"Đối với III(D) Performance Presentation, hệ thống kiểm soát phải đi từ nhận diện nguồn rủi ro đến hành động khắc phục và lưu dấu vết: Performance data controls, standardized reporting periods, performance reconciliation và independent review. Một quy trình chỉ hiệu quả khi người chịu trách nhiệm, thời điểm kiểm tra và cơ chế escalation được xác định rõ, không chỉ ghi “tuân thủ quy định” chung chung."},{"id":"S02-12","los_ids":["CFA26-10-03-LOS02"],"heading_vi":"III(E) — thiết kế kiểm soát phòng ngừa","body_vi":"Đối với III(E) Preservation of Confidentiality, hệ thống kiểm soát phải đi từ nhận diện nguồn rủi ro đến hành động khắc phục và lưu dấu vết: Role-based access, encryption, written consent, documented disclosure exceptions và privacy controls. Một quy trình chỉ hiệu quả khi người chịu trách nhiệm, thời điểm kiểm tra và cơ chế escalation được xác định rõ, không chỉ ghi “tuân thủ quy định” chung chung."},{"id":"S02-13","los_ids":["CFA26-10-03-LOS02"],"heading_vi":"IV(A) — thiết kế kiểm soát phòng ngừa","body_vi":"Đối với IV(A) Loyalty, hệ thống kiểm soát phải đi từ nhận diện nguồn rủi ro đến hành động khắc phục và lưu dấu vết: Clear exit procedures, confidentiality notices, access revocation, noncompete rules theo luật. Một quy trình chỉ hiệu quả khi người chịu trách nhiệm, thời điểm kiểm tra và cơ chế escalation được xác định rõ, không chỉ ghi “tuân thủ quy định” chung chung."},{"id":"S02-14","los_ids":["CFA26-10-03-LOS02"],"heading_vi":"IV(B) — thiết kế kiểm soát phòng ngừa","body_vi":"Đối với IV(B) Additional Compensation Arrangements, hệ thống kiểm soát phải đi từ nhận diện nguồn rủi ro đến hành động khắc phục và lưu dấu vết: Written pre-approval form, registry outside compensation, disclosure review và record retention. Một quy trình chỉ hiệu quả khi người chịu trách nhiệm, thời điểm kiểm tra và cơ chế escalation được xác định rõ, không chỉ ghi “tuân thủ quy định” chung chung."},{"id":"S02-15","los_ids":["CFA26-10-03-LOS02"],"heading_vi":"IV(C) — thiết kế kiểm soát phòng ngừa","body_vi":"Đối với IV(C) Responsibilities of Supervisors, hệ thống kiểm soát phải đi từ nhận diện nguồn rủi ro đến hành động khắc phục và lưu dấu vết: Written supervision map, regular sampling review, training, escalation and remediation logs. Một quy trình chỉ hiệu quả khi người chịu trách nhiệm, thời điểm kiểm tra và cơ chế escalation được xác định rõ, không chỉ ghi “tuân thủ quy định” chung chung."},{"id":"S02-16","los_ids":["CFA26-10-03-LOS02"],"heading_vi":"V(A) — thiết kế kiểm soát phòng ngừa","body_vi":"Đối với V(A) Diligence and Reasonable Basis, hệ thống kiểm soát phải đi từ nhận diện nguồn rủi ro đến hành động khắc phục và lưu dấu vết: Research sign-off, independent model validation, data/vendor due diligence và change logs. Một quy trình chỉ hiệu quả khi người chịu trách nhiệm, thời điểm kiểm tra và cơ chế escalation được xác định rõ, không chỉ ghi “tuân thủ quy định” chung chung."},{"id":"S02-17","los_ids":["CFA26-10-03-LOS02"],"heading_vi":"V(B) — thiết kế kiểm soát phòng ngừa","body_vi":"Đối với V(B) Communication with Clients and Prospective Clients, hệ thống kiểm soát phải đi từ nhận diện nguồn rủi ro đến hành động khắc phục và lưu dấu vết: Standardized fee and risk disclosure, fact/opinion labels, review of client materials và update notice. Một quy trình chỉ hiệu quả khi người chịu trách nhiệm, thời điểm kiểm tra và cơ chế escalation được xác định rõ, không chỉ ghi “tuân thủ quy định” chung chung."},{"id":"S02-18","los_ids":["CFA26-10-03-LOS02"],"heading_vi":"V(C) — thiết kế kiểm soát phòng ngừa","body_vi":"Đối với V(C) Record Retention, hệ thống kiểm soát phải đi từ nhận diện nguồn rủi ro đến hành động khắc phục và lưu dấu vết: Document-management retention rules, approved repositories, audit trails, periodic access/retrieval tests. Một quy trình chỉ hiệu quả khi người chịu trách nhiệm, thời điểm kiểm tra và cơ chế escalation được xác định rõ, không chỉ ghi “tuân thủ quy định” chung chung."},{"id":"S02-19","los_ids":["CFA26-10-03-LOS02"],"heading_vi":"VI(A) — thiết kế kiểm soát phòng ngừa","body_vi":"Đối với VI(A) Avoid or Disclose Conflicts, hệ thống kiểm soát phải đi từ nhận diện nguồn rủi ro đến hành động khắc phục và lưu dấu vết: Conflicts inventory, pre-approval, prominent client disclosures, independent oversight. Một quy trình chỉ hiệu quả khi người chịu trách nhiệm, thời điểm kiểm tra và cơ chế escalation được xác định rõ, không chỉ ghi “tuân thủ quy định” chung chung."},{"id":"S02-20","los_ids":["CFA26-10-03-LOS02"],"heading_vi":"VI(B) — thiết kế kiểm soát phòng ngừa","body_vi":"Đối với VI(B) Priority of Transactions, hệ thống kiểm soát phải đi từ nhận diện nguồn rủi ro đến hành động khắc phục và lưu dấu vết: Personal-trade preclearance, restricted list, order time-stamps và surveillance. Một quy trình chỉ hiệu quả khi người chịu trách nhiệm, thời điểm kiểm tra và cơ chế escalation được xác định rõ, không chỉ ghi “tuân thủ quy định” chung chung."},{"id":"S02-21","los_ids":["CFA26-10-03-LOS02"],"heading_vi":"VI(C) — thiết kế kiểm soát phòng ngừa","body_vi":"Đối với VI(C) Referral Fees, hệ thống kiểm soát phải đi từ nhận diện nguồn rủi ro đến hành động khắc phục và lưu dấu vết: Referral agreement inventory, standardized referral disclosures, conflict review. Một quy trình chỉ hiệu quả khi người chịu trách nhiệm, thời điểm kiểm tra và cơ chế escalation được xác định rõ, không chỉ ghi “tuân thủ quy định” chung chung."},{"id":"S02-22","los_ids":["CFA26-10-03-LOS02"],"heading_vi":"VII(A) — thiết kế kiểm soát phòng ngừa","body_vi":"Đối với VII(A) Conduct as Participants in CFA Institute Programs, hệ thống kiểm soát phải đi từ nhận diện nguồn rủi ro đến hành động khắc phục và lưu dấu vết: Exam confidentiality training, social-media rules và reporting channels. Một quy trình chỉ hiệu quả khi người chịu trách nhiệm, thời điểm kiểm tra và cơ chế escalation được xác định rõ, không chỉ ghi “tuân thủ quy định” chung chung."},{"id":"S02-23","los_ids":["CFA26-10-03-LOS02"],"heading_vi":"VII(B) — thiết kế kiểm soát phòng ngừa","body_vi":"Đối với VII(B) Reference to CFA Institute, CFA Designation, and CFA Program, hệ thống kiểm soát phải đi từ nhận diện nguồn rủi ro đến hành động khắc phục và lưu dấu vết: Review job titles/marketing, standardized credential wording và periodic public-profile audit. Một quy trình chỉ hiệu quả khi người chịu trách nhiệm, thời điểm kiểm tra và cơ chế escalation được xác định rõ, không chỉ ghi “tuân thủ quy định” chung chung."},{"id":"S02-24","los_ids":["CFA26-10-03-LOS02"],"heading_vi":"Governance, training và giám sát độc lập","body_vi":"Trước khi xảy ra violation, firms nên xây compliance manual, chương trình kiểm soát conflicts, đào tạo và kiểm định competence, review disclosures, ethical reporting và kỷ luật độc lập. Mỗi tuyến kiểm soát cần xác định ai duyệt và ai lưu chứng từ; manager vẫn có trách nhiệm giám sát dù công ty đã có compliance officer."},{"id":"S03-01","los_ids":["CFA26-10-03-LOS03"],"heading_vi":"I(A) — phân biệt conforming và violating conduct","body_vi":"Tình huống vi phạm I(A): Researcher được yêu cầu bán một tài sản bị cấm theo quy định sở tại dù Code không nhắc đến sản phẩm đó. Hành vi đáp ứng chuẩn cần là: Từ chối thực hiện, báo compliance, lưu quyết định, theo quy định pháp luật nghiêm ngặt hơn. Khi làm câu CFA phải đọc facts về thời điểm, consent, mức disclosure và consequences; cùng một sản phẩm/tin tức có thể có kết luận khác nếu các tình tiết cốt lõi thay đổi."},{"id":"S03-02","los_ids":["CFA26-10-03-LOS03"],"heading_vi":"I(B) — phân biệt conforming và violating conduct","body_vi":"Tình huống vi phạm I(B): Issuer trả toàn bộ kỳ nghỉ cao cấp để analyst đưa ra khuyến nghị mua, analyst chấp nhận và hứa nâng rating. Hành vi đáp ứng chuẩn cần là: Từ chối hoặc xử lý theo chính sách independent research; để công ty kiểm soát gifts và phân tách bộ phận investment banking. Khi làm câu CFA phải đọc facts về thời điểm, consent, mức disclosure và consequences; cùng một sản phẩm/tin tức có thể có kết luận khác nếu các tình tiết cốt lõi thay đổi."},{"id":"S03-03","los_ids":["CFA26-10-03-LOS03"],"heading_vi":"I(C) — phân biệt conforming và violating conduct","body_vi":"Tình huống vi phạm I(C): Advisor tự nhận đã tạo model của đồng nghiệp và ghi “bảo đảm lợi nhuận 15% mỗi năm”. Hành vi đáp ứng chuẩn cần là: Ghi nguồn rõ ràng, công bố assumptions, nhấn mạnh forecast không phải cam kết và xác minh dữ liệu. Khi làm câu CFA phải đọc facts về thời điểm, consent, mức disclosure và consequences; cùng một sản phẩm/tin tức có thể có kết luận khác nếu các tình tiết cốt lõi thay đổi."},{"id":"S03-04","los_ids":["CFA26-10-03-LOS03"],"heading_vi":"I(D) — phân biệt conforming và violating conduct","body_vi":"Tình huống vi phạm I(D): Portfolio manager sửa hóa đơn để nhận khoản hoàn trả chi phí không phát sinh. Hành vi đáp ứng chuẩn cần là: Không gian lận expense records, báo nội bộ khi cần và chịu trách nhiệm sửa sai. Khi làm câu CFA phải đọc facts về thời điểm, consent, mức disclosure và consequences; cùng một sản phẩm/tin tức có thể có kết luận khác nếu các tình tiết cốt lõi thay đổi."},{"id":"S03-05","los_ids":["CFA26-10-03-LOS03"],"heading_vi":"I(E) — phân biệt conforming và violating conduct","body_vi":"Tình huống vi phạm I(E): Analyst không hiểu cấu trúc path-dependent options nhưng vẫn công bố valuation “đã xác minh”. Hành vi đáp ứng chuẩn cần là: Học/tham vấn chuyên môn, kiểm định pricing và nói rõ hạn chế trước khi khuyến nghị. Khi làm câu CFA phải đọc facts về thời điểm, consent, mức disclosure và consequences; cùng một sản phẩm/tin tức có thể có kết luận khác nếu các tình tiết cốt lõi thay đổi."},{"id":"S03-06","los_ids":["CFA26-10-03-LOS03"],"heading_vi":"II(A) — phân biệt conforming và violating conduct","body_vi":"Tình huống vi phạm II(A): Analyst biết kết quả sáp nhập bí mật từ CFO và mua cổ phiếu trước thông báo. Hành vi đáp ứng chuẩn cần là: Không giao dịch/gợi ý người khác; báo compliance, restricted list và chờ thông tin public được phổ biến. Khi làm câu CFA phải đọc facts về thời điểm, consent, mức disclosure và consequences; cùng một sản phẩm/tin tức có thể có kết luận khác nếu các tình tiết cốt lõi thay đổi."},{"id":"S03-07","los_ids":["CFA26-10-03-LOS03"],"heading_vi":"II(B) — phân biệt conforming và violating conduct","body_vi":"Tình huống vi phạm II(B): Trader đặt lệnh ảo lớn để tạo cảm giác demand cao rồi hủy trước khi khớp. Hành vi đáp ứng chuẩn cần là: Giao dịch phản ánh nhu cầu thực và thông tin trung thực, không tạo tín hiệu order book giả. Khi làm câu CFA phải đọc facts về thời điểm, consent, mức disclosure và consequences; cùng một sản phẩm/tin tức có thể có kết luận khác nếu các tình tiết cốt lõi thay đổi."},{"id":"S03-08","los_ids":["CFA26-10-03-LOS03"],"heading_vi":"III(A) — phân biệt conforming và violating conduct","body_vi":"Tình huống vi phạm III(A): Manager chọn broker phí cao có liên quan cá nhân dù execution quality kém. Hành vi đáp ứng chuẩn cần là: Đánh giá execution net of costs cho khách hàng, không ưu tiên affiliate nếu bất lợi. Khi làm câu CFA phải đọc facts về thời điểm, consent, mức disclosure và consequences; cùng một sản phẩm/tin tức có thể có kết luận khác nếu các tình tiết cốt lõi thay đổi."},{"id":"S03-09","los_ids":["CFA26-10-03-LOS03"],"heading_vi":"III(B) — phân biệt conforming và violating conduct","body_vi":"Tình huống vi phạm III(B): Analyst gửi khuyến nghị mới cho nhóm bạn bè một ngày trước các khách hàng khác cùng loại dịch vụ. Hành vi đáp ứng chuẩn cần là: Thiết lập phân phối đồng thời, trade allocation công bằng và có hồ sơ lý do nếu hạn chế thanh khoản. Khi làm câu CFA phải đọc facts về thời điểm, consent, mức disclosure và consequences; cùng một sản phẩm/tin tức có thể có kết luận khác nếu các tình tiết cốt lõi thay đổi."},{"id":"S03-10","los_ids":["CFA26-10-03-LOS03"],"heading_vi":"III(C) — phân biệt conforming và violating conduct","body_vi":"Tình huống vi phạm III(C): Advisor đặt 60% vốn hưu trí cho khách sắp nghỉ vào tài sản leveraged illiquid dù cần rút tiền năm tới. Hành vi đáp ứng chuẩn cần là: Thu thập liquidity horizon/risk tolerance, đánh giá portfolio-level concentration, chỉ khuyến nghị phù hợp. Khi làm câu CFA phải đọc facts về thời điểm, consent, mức disclosure và consequences; cùng một sản phẩm/tin tức có thể có kết luận khác nếu các tình tiết cốt lõi thay đổi."},{"id":"S03-11","los_ids":["CFA26-10-03-LOS03"],"heading_vi":"III(D) — phân biệt conforming và violating conduct","body_vi":"Tình huống vi phạm III(D): Manager giới thiệu “5 năm lợi nhuận cao” nhưng chỉ chọn tài khoản thắng lớn, bỏ tất cả tài khoản lỗ. Hành vi đáp ứng chuẩn cần là: Công bố phương pháp, time windows nhất quán, nêu limitations và số liệu đầy đủ, rõ gross/net. Khi làm câu CFA phải đọc facts về thời điểm, consent, mức disclosure và consequences; cùng một sản phẩm/tin tức có thể có kết luận khác nếu các tình tiết cốt lõi thay đổi."},{"id":"S03-12","los_ids":["CFA26-10-03-LOS03"],"heading_vi":"III(E) — phân biệt conforming và violating conduct","body_vi":"Tình huống vi phạm III(E): Advisor chuyển danh sách khách VIP cho người quen làm bảo hiểm dù chưa có đồng ý. Hành vi đáp ứng chuẩn cần là: Chỉ chia sẻ trong phạm vi được phép hoặc theo legal requirement, bảo vệ file và access. Khi làm câu CFA phải đọc facts về thời điểm, consent, mức disclosure và consequences; cùng một sản phẩm/tin tức có thể có kết luận khác nếu các tình tiết cốt lõi thay đổi."},{"id":"S03-13","los_ids":["CFA26-10-03-LOS03"],"heading_vi":"IV(A) — phân biệt conforming và violating conduct","body_vi":"Tình huống vi phạm IV(A): Employee tải về toàn bộ client list mật rồi chuyển sang competitor trước ngày nghỉ. Hành vi đáp ứng chuẩn cần là: Giữ bí mật, tuân hợp đồng, chỉ dùng thông tin public/mối quan hệ hợp pháp sau nghỉ. Khi làm câu CFA phải đọc facts về thời điểm, consent, mức disclosure và consequences; cùng một sản phẩm/tin tức có thể có kết luận khác nếu các tình tiết cốt lõi thay đổi."},{"id":"S03-14","los_ids":["CFA26-10-03-LOS03"],"heading_vi":"IV(B) — phân biệt conforming và violating conduct","body_vi":"Tình huống vi phạm IV(B): Manager nhận bonus riêng từ client nếu vượt index nhưng không xin phép employer. Hành vi đáp ứng chuẩn cần là: Xin written consent từ employer và bên liên quan trước khi chấp nhận arrangement. Khi làm câu CFA phải đọc facts về thời điểm, consent, mức disclosure và consequences; cùng một sản phẩm/tin tức có thể có kết luận khác nếu các tình tiết cốt lõi thay đổi."},{"id":"S03-15","los_ids":["CFA26-10-03-LOS03"],"heading_vi":"IV(C) — phân biệt conforming và violating conduct","body_vi":"Tình huống vi phạm IV(C): Team leader biết research analysts bị pressure viết báo cáo giả nhưng không thiết lập review hay xử lý. Hành vi đáp ứng chuẩn cần là: Triển khai procedures phát hiện/phòng vi phạm, audit và hành động sửa khi có red flags. Khi làm câu CFA phải đọc facts về thời điểm, consent, mức disclosure và consequences; cùng một sản phẩm/tin tức có thể có kết luận khác nếu các tình tiết cốt lõi thay đổi."},{"id":"S03-16","los_ids":["CFA26-10-03-LOS03"],"heading_vi":"V(A) — phân biệt conforming và violating conduct","body_vi":"Tình huống vi phạm V(A): Analyst upgrade stock vì một bài đăng ẩn danh không kiểm chứng trên mạng xã hội. Hành vi đáp ứng chuẩn cần là: Kiểm tra data, model assumptions, issuer information, downside risk và evidence phù hợp. Khi làm câu CFA phải đọc facts về thời điểm, consent, mức disclosure và consequences; cùng một sản phẩm/tin tức có thể có kết luận khác nếu các tình tiết cốt lõi thay đổi."},{"id":"S03-17","los_ids":["CFA26-10-03-LOS03"],"heading_vi":"V(B) — phân biệt conforming và violating conduct","body_vi":"Tình huống vi phạm V(B): Adviser bán strategy phí cao nhưng che management/exit fees và cam kết return dự phóng như thực tế. Hành vi đáp ứng chuẩn cần là: Trình bày phí rõ, risks, assumptions, model uncertainties và material changes cho client. Khi làm câu CFA phải đọc facts về thời điểm, consent, mức disclosure và consequences; cùng một sản phẩm/tin tức có thể có kết luận khác nếu các tình tiết cốt lõi thay đổi."},{"id":"S03-18","los_ids":["CFA26-10-03-LOS03"],"heading_vi":"V(C) — phân biệt conforming và violating conduct","body_vi":"Tình huống vi phạm V(C): Analyst xóa toàn bộ supporting model sau khi khách hàng đầu tư, không thể chứng minh thesis. Hành vi đáp ứng chuẩn cần là: Lưu data/model và versions đủ tái lập rationale; bàn giao records theo chính sách employer. Khi làm câu CFA phải đọc facts về thời điểm, consent, mức disclosure và consequences; cùng một sản phẩm/tin tức có thể có kết luận khác nếu các tình tiết cốt lõi thay đổi."},{"id":"S03-19","los_ids":["CFA26-10-03-LOS03"],"heading_vi":"VI(A) — phân biệt conforming và violating conduct","body_vi":"Tình huống vi phạm VI(A): Analyst sở hữu lượng lớn cổ phiếu đang khuyến nghị mua mà chỉ ghi “có thể có lợi ích”. Hành vi đáp ứng chuẩn cần là: Avoid coverage nếu ảnh hưởng objectivity, hoặc disclose cụ thể holdings và implications rõ ràng. Khi làm câu CFA phải đọc facts về thời điểm, consent, mức disclosure và consequences; cùng một sản phẩm/tin tức có thể có kết luận khác nếu các tình tiết cốt lõi thay đổi."},{"id":"S03-20","los_ids":["CFA26-10-03-LOS03"],"heading_vi":"VI(B) — phân biệt conforming và violating conduct","body_vi":"Tình huống vi phạm VI(B): Trader mua trước cho tài khoản cá nhân ngay khi biết lệnh mua lớn của client sẽ được thực hiện. Hành vi đáp ứng chuẩn cần là: Thực hiện client/employer transactions trước, tuân personal dealing restrictions. Khi làm câu CFA phải đọc facts về thời điểm, consent, mức disclosure và consequences; cùng một sản phẩm/tin tức có thể có kết luận khác nếu các tình tiết cốt lõi thay đổi."},{"id":"S03-21","los_ids":["CFA26-10-03-LOS03"],"heading_vi":"VI(C) — phân biệt conforming và violating conduct","body_vi":"Tình huống vi phạm VI(C): Advisor giới thiệu một manager và nhận 1% assets mà không disclosure cho khách. Hành vi đáp ứng chuẩn cần là: Nêu rõ bản chất và mức/ước lượng khoản referral compensation trước khi client quyết định. Khi làm câu CFA phải đọc facts về thời điểm, consent, mức disclosure và consequences; cùng một sản phẩm/tin tức có thể có kết luận khác nếu các tình tiết cốt lõi thay đổi."},{"id":"S03-22","los_ids":["CFA26-10-03-LOS03"],"heading_vi":"VII(A) — phân biệt conforming và violating conduct","body_vi":"Tình huống vi phạm VII(A): Candidate đăng các câu và đáp án cụ thể vừa gặp ở exam lên nhóm chat. Hành vi đáp ứng chuẩn cần là: Giữ bí mật exam content; có thể nêu nhận xét chung về trải nghiệm mà không tiết lộ nội dung bảo mật. Khi làm câu CFA phải đọc facts về thời điểm, consent, mức disclosure và consequences; cùng một sản phẩm/tin tức có thể có kết luận khác nếu các tình tiết cốt lõi thay đổi."},{"id":"S03-23","los_ids":["CFA26-10-03-LOS03"],"heading_vi":"VII(B) — phân biệt conforming và violating conduct","body_vi":"Tình huống vi phạm VII(B): Candidate ghi “CFA Level I certified expert, CFA guarantees 20% annual returns”. Hành vi đáp ứng chuẩn cần là: Ghi đúng “passed Level I of CFA Program” khi thực sự qua, tránh claims performance guarantees. Khi làm câu CFA phải đọc facts về thời điểm, consent, mức disclosure và consequences; cùng một sản phẩm/tin tức có thể có kết luận khác nếu các tình tiết cốt lõi thay đổi."},{"id":"S03-24","los_ids":["CFA26-10-03-LOS03"],"heading_vi":"Một tình huống có thể vi phạm nhiều Standards","body_vi":"Ví dụ analyst giao dịch trước client order đồng thời chia sẻ MNPI: VI(B) và II(A) có thể đồng thời áp dụng, thêm I(B)/VI(A) nếu có conflict. Phân tích từng hành vi riêng, nhận diện phạm vi client/employer và thời điểm giao dịch; không dừng ở Standard đầu tiên xuất hiện trong đề."}],"formulae":[{"id":"F01-01","los_ids":["CFA26-10-03-LOS01"],"expression":"Ethical assessment = evidence of conduct + applicable Standard + stakeholders + remedy","variables":["Descriptive framework only; not a mathematical formula prescribed by CFA Institute."],"assumptions":["Every decision depends on specific case facts and applicable requirements."]},{"id":"F02-01","los_ids":["CFA26-10-03-LOS02"],"expression":"Ethical assessment = evidence of conduct + applicable Standard + stakeholders + remedy","variables":["Descriptive framework only; not a mathematical formula prescribed by CFA Institute."],"assumptions":["Every decision depends on specific case facts and applicable requirements."]},{"id":"F03-01","los_ids":["CFA26-10-03-LOS03"],"expression":"Ethical assessment = evidence of conduct + applicable Standard + stakeholders + remedy","variables":["Descriptive framework only; not a mathematical formula prescribed by CFA Institute."],"assumptions":["Every decision depends on specific case facts and applicable requirements."]}],"worked_examples":[{"id":"E01-01","los_ids":["CFA26-10-03-LOS01"],"problem":"Research team phát hiện vừa có tín hiệu thao túng cổ phiếu, vừa có thông tin nội bộ trọng yếu chưa công khai.","solution_steps":["Phân biệt II(A) MNPI với II(B) manipulation: giao dịch trên tin mật và order tạo volume giả là hai vi phạm độc lập.","Quyết định không giao dịch, báo compliance, kiểm tra restricted list và lưu chứng từ."],"answer":"Không đánh đồng manipulation với insider trading; kết luận có thể bao gồm cả hai."},{"id":"E01-02","los_ids":["CFA26-10-03-LOS01"],"problem":"Client có khuyến nghị illiquid private fund và adviser đang nhận phí referral bí mật.","solution_steps":["III(C) đánh giá suitability theo toàn danh mục và liquidity, VI(C) yêu cầu referral disclosure.","VI(A) cũng phải xem xét conflict; nếu không thể quản lý khách quan phải avoid transaction."],"answer":"Áp dụng nhiều Standards và chỉ ra remedies cụ thể, không chỉ gọi “xung đột lợi ích”."},{"id":"E02-01","los_ids":["CFA26-10-03-LOS02"],"problem":"Brokerage đưa ra policy cấm front-running nhưng không có pretrade approval.","solution_steps":["VI(B) cần priority clients/employer và logs xác minh timing.","Bổ sung preclearance cho personal accounts, surveillance và trách nhiệm kiểm toán."],"answer":"Một câu policy không đủ nếu không có controls có thể kiểm chứng."},{"id":"E02-02","los_ids":["CFA26-10-03-LOS02"],"problem":"Analyst đã ghi disclosure conflicts nhưng chưa được đào tạo rủi ro structured bonds.","solution_steps":["I(E) vẫn yêu cầu competence, V(A) reasonable basis độc lập với việc disclosure VI(A).","Tổ chức training, specialist review, benchmark model và escalation trước recommendation."],"answer":"Controls cần bao phủ cả technical ability, không chỉ conflict disclosure."},{"id":"E03-01","los_ids":["CFA26-10-03-LOS03"],"problem":"Manager sử dụng commission affiliate cao hơn nhưng không phân tích best execution.","solution_steps":["Phí cao không luôn là violation nếu execution tốt và net client value hợp lý; cần kiểm tra duty III(A).","Nếu quyết định chỉ vì personal commission và client net benefit bị thiệt, có dấu hiệu vi phạm III(A)/VI(A)."],"answer":"Tìm facts để phân biệt vi phạm và phù hợp, không kết luận từ một từ khóa."},{"id":"E03-02","los_ids":["CFA26-10-03-LOS03"],"problem":"Nghiên cứu có số liệu mới chưa công bố nhưng không trọng yếu, kết hợp với public data tạo khuyến nghị.","solution_steps":["Mosaic theory có thể cho phép research dựa trên public + nonmaterial nonpublic information.","Nếu dữ liệu chưa công bố lại material và analyst giao dịch, II(A) bị áp dụng."],"answer":"Cùng chữ “nonpublic” không tự động cấu thành vi phạm: phải xét materiality."}],"questions":[{"id":"Q01-01","los_ids":["CFA26-10-03-LOS01"],"stem":"Đối với I(A) Knowledge of the Law, hành động nào phù hợp nhất?","options":["Áp dụng cách hành xử phù hợp: Từ chối thực hiện, báo compliance, lưu quyết định, theo quy định pháp luật nghiêm ngặt hơn.","Giữ bí mật vấn đề để không làm employer khó chịu","Thực hiện tình huống này vì “mọi người đều làm”"],"correct_option":0,"explanation":"I(A): Khi làm việc ở nhiều jurisdiction, phải xác định applicable laws/rules, CFA Code/Standards và áp dụng mức nghiêm ngặt hơn khi có khác biệt. Không được knowingly assist violation; phải dissociate khỏi hành vi sai. Vì thế cần giải quyết thực chất tình huống, thay vì dựa vào sự im lặng, tập quán thị trường hoặc lợi ích cá nhân."},{"id":"Q01-02","los_ids":["CFA26-10-03-LOS01"],"stem":"Đối với I(B) Independence and Objectivity, hành động nào phù hợp nhất?","options":["Thực hiện tình huống này vì “mọi người đều làm”","Áp dụng cách hành xử phù hợp: Từ chối hoặc xử lý theo chính sách independent research; để công ty kiểm soát gifts và phân tách bộ phận investment banking.","Giữ bí mật vấn đề để không làm employer khó chịu"],"correct_option":1,"explanation":"I(B): Giữ independent professional judgment trước quà tặng, hospitality, travel, investment-banking pressure hay bên bán nghiên cứu. Giá trị quà có thể ảnh hưởng tính khách quan; disclosure không luôn chữa được ảnh hưởng thực chất. Vì thế cần giải quyết thực chất tình huống, thay vì dựa vào sự im lặng, tập quán thị trường hoặc lợi ích cá nhân."},{"id":"Q01-03","los_ids":["CFA26-10-03-LOS01"],"stem":"Đối với I(C) Misrepresentation, hành động nào phù hợp nhất?","options":["Giữ bí mật vấn đề để không làm employer khó chịu","Thực hiện tình huống này vì “mọi người đều làm”","Áp dụng cách hành xử phù hợp: Ghi nguồn rõ ràng, công bố assumptions, nhấn mạnh forecast không phải cam kết và xác minh dữ liệu."],"correct_option":2,"explanation":"I(C): Không cố tình trình bày sai phương pháp, credentials, track record, forecast là fact, hoặc dùng tài liệu của người khác không ghi nguồn. Không dùng charts chọn kỳ thuận lợi để tạo ấn tượng sai lệch. Vì thế cần giải quyết thực chất tình huống, thay vì dựa vào sự im lặng, tập quán thị trường hoặc lợi ích cá nhân."},{"id":"Q01-04","los_ids":["CFA26-10-03-LOS01"],"stem":"Đối với I(D) Misconduct, hành động nào phù hợp nhất?","options":["Áp dụng cách hành xử phù hợp: Không gian lận expense records, báo nội bộ khi cần và chịu trách nhiệm sửa sai.","Giữ bí mật vấn đề để không làm employer khó chịu","Thực hiện tình huống này vì “mọi người đều làm”"],"correct_option":0,"explanation":"I(D): Cấm hành vi nghề nghiệp dishonesty, fraud, deceit hoặc hành vi phản ánh bất lợi tới reputation, integrity và competence. Không phải mọi vi phạm luật riêng tư đều tự động là professional misconduct, cần xét tính liên quan và facts. Vì thế cần giải quyết thực chất tình huống, thay vì dựa vào sự im lặng, tập quán thị trường hoặc lợi ích cá nhân."},{"id":"Q01-05","los_ids":["CFA26-10-03-LOS01"],"stem":"Đối với I(E) Competence, hành động nào phù hợp nhất?","options":["Thực hiện tình huống này vì “mọi người đều làm”","Áp dụng cách hành xử phù hợp: Học/tham vấn chuyên môn, kiểm định pricing và nói rõ hạn chế trước khi khuyến nghị.","Giữ bí mật vấn đề để không làm employer khó chịu"],"correct_option":1,"explanation":"I(E): Phải có và duy trì năng lực thực tế cần thiết cho nhiệm vụ chuyên môn; không nhất thiết có một số giờ continuing education cố định cho mọi công việc. Khi chuyển sản phẩm phức tạp phải học hoặc tìm chuyên gia. Vì thế cần giải quyết thực chất tình huống, thay vì dựa vào sự im lặng, tập quán thị trường hoặc lợi ích cá nhân."},{"id":"Q01-06","los_ids":["CFA26-10-03-LOS01"],"stem":"Đối với II(A) Material Nonpublic Information, hành động nào phù hợp nhất?","options":["Giữ bí mật vấn đề để không làm employer khó chịu","Thực hiện tình huống này vì “mọi người đều làm”","Áp dụng cách hành xử phù hợp: Không giao dịch/gợi ý người khác; báo compliance, restricted list và chờ thông tin public được phổ biến."],"correct_option":2,"explanation":"II(A): Người nắm material nonpublic information có thể ảnh hưởng giá đầu tư không được trading hoặc khiến người khác trading trên thông tin đó. Mosaic theory cho phép public plus nonmaterial nonpublic info được phân tích hợp pháp. Vì thế cần giải quyết thực chất tình huống, thay vì dựa vào sự im lặng, tập quán thị trường hoặc lợi ích cá nhân."},{"id":"Q01-07","los_ids":["CFA26-10-03-LOS01"],"stem":"Đối với II(B) Market Manipulation, hành động nào phù hợp nhất?","options":["Áp dụng cách hành xử phù hợp: Giao dịch phản ánh nhu cầu thực và thông tin trung thực, không tạo tín hiệu order book giả.","Giữ bí mật vấn đề để không làm employer khó chịu","Thực hiện tình huống này vì “mọi người đều làm”"],"correct_option":0,"explanation":"II(B): Cấm hành vi bóp méo prices hoặc làm tăng volume giả tạo với intent gây hiểu nhầm. Giao dịch hợp pháp dựa trên phân tích thực khác với spoofing, wash trades hoặc tin giả nhằm thao túng. Vì thế cần giải quyết thực chất tình huống, thay vì dựa vào sự im lặng, tập quán thị trường hoặc lợi ích cá nhân."},{"id":"Q01-08","los_ids":["CFA26-10-03-LOS01"],"stem":"Đối với III(A) Loyalty, Prudence, and Care, hành động nào phù hợp nhất?","options":["Thực hiện tình huống này vì “mọi người đều làm”","Áp dụng cách hành xử phù hợp: Đánh giá execution net of costs cho khách hàng, không ưu tiên affiliate nếu bất lợi.","Giữ bí mật vấn đề để không làm employer khó chịu"],"correct_option":1,"explanation":"III(A): Trong nhiệm vụ với khách hàng, đặt lợi ích clients lên trước employer và bản thân; xử lý tài sản được ủy thác cẩn trọng, không làm lợi công ty bằng fees không minh bạch hoặc giao dịch bất lợi. Vì thế cần giải quyết thực chất tình huống, thay vì dựa vào sự im lặng, tập quán thị trường hoặc lợi ích cá nhân."},{"id":"Q01-09","los_ids":["CFA26-10-03-LOS01"],"stem":"Đối với III(B) Fair Dealing, hành động nào phù hợp nhất?","options":["Giữ bí mật vấn đề để không làm employer khó chịu","Thực hiện tình huống này vì “mọi người đều làm”","Áp dụng cách hành xử phù hợp: Thiết lập phân phối đồng thời, trade allocation công bằng và có hồ sơ lý do nếu hạn chế thanh khoản."],"correct_option":2,"explanation":"III(B): Đối xử fair, objective với tất cả clients về research, recommendations và trade actions; fair không bắt buộc identical timing tuyệt đối, nhưng không cố ý thiên vị một nhóm vì phí cao. Vì thế cần giải quyết thực chất tình huống, thay vì dựa vào sự im lặng, tập quán thị trường hoặc lợi ích cá nhân."},{"id":"Q01-10","los_ids":["CFA26-10-03-LOS01"],"stem":"Đối với III(C) Suitability, hành động nào phù hợp nhất?","options":["Áp dụng cách hành xử phù hợp: Thu thập liquidity horizon/risk tolerance, đánh giá portfolio-level concentration, chỉ khuyến nghị phù hợp.","Giữ bí mật vấn đề để không làm employer khó chịu","Thực hiện tình huống này vì “mọi người đều làm”"],"correct_option":0,"explanation":"III(C): Trong advisory relationship phải cập nhật objectives, risk/return profile, financial constraints và xem suitability trong context tổng portfolio. Khi quản lý mandate cụ thể, chỉ hành động phù hợp mandate đã công bố. Vì thế cần giải quyết thực chất tình huống, thay vì dựa vào sự im lặng, tập quán thị trường hoặc lợi ích cá nhân."},{"id":"Q01-11","los_ids":["CFA26-10-03-LOS01"],"stem":"Đối với III(D) Performance Presentation, hành động nào phù hợp nhất?","options":["Thực hiện tình huống này vì “mọi người đều làm”","Áp dụng cách hành xử phù hợp: Công bố phương pháp, time windows nhất quán, nêu limitations và số liệu đầy đủ, rõ gross/net.","Giữ bí mật vấn đề để không làm employer khó chịu"],"correct_option":1,"explanation":"III(D): Trình bày kết quả fair, accurate, complete; không dùng selective periods, loại losing accounts hay số gross/net không rõ để đánh lừa. Có thể dùng composites phù hợp, disclosed methodology. Vì thế cần giải quyết thực chất tình huống, thay vì dựa vào sự im lặng, tập quán thị trường hoặc lợi ích cá nhân."},{"id":"Q01-12","los_ids":["CFA26-10-03-LOS01"],"stem":"Đối với III(E) Preservation of Confidentiality, hành động nào phù hợp nhất?","options":["Giữ bí mật vấn đề để không làm employer khó chịu","Thực hiện tình huống này vì “mọi người đều làm”","Áp dụng cách hành xử phù hợp: Chỉ chia sẻ trong phạm vi được phép hoặc theo legal requirement, bảo vệ file và access."],"correct_option":2,"explanation":"III(E): Bảo mật thông tin current, former và prospective clients; exceptions: client illegal activities, disclosure required by law, hoặc client permission. Không tự chia sẻ tên khách cho marketing bên thứ ba. Vì thế cần giải quyết thực chất tình huống, thay vì dựa vào sự im lặng, tập quán thị trường hoặc lợi ích cá nhân."},{"id":"Q01-13","los_ids":["CFA26-10-03-LOS01"],"stem":"Đối với IV(A) Loyalty, hành động nào phù hợp nhất?","options":["Áp dụng cách hành xử phù hợp: Giữ bí mật, tuân hợp đồng, chỉ dùng thông tin public/mối quan hệ hợp pháp sau nghỉ.","Giữ bí mật vấn đề để không làm employer khó chịu","Thực hiện tình huống này vì “mọi người đều làm”"],"correct_option":0,"explanation":"IV(A): Không gây hại employer trong professional activities, không tiết lộ bí mật hoặc lấy cắp sản phẩm nghiên cứu; việc chuẩn bị mở doanh nghiệp sau khi nghỉ cần phân biệt với cạnh tranh gây hại khi còn làm. Vì thế cần giải quyết thực chất tình huống, thay vì dựa vào sự im lặng, tập quán thị trường hoặc lợi ích cá nhân."},{"id":"Q01-14","los_ids":["CFA26-10-03-LOS01"],"stem":"Đối với IV(B) Additional Compensation Arrangements, hành động nào phù hợp nhất?","options":["Thực hiện tình huống này vì “mọi người đều làm”","Áp dụng cách hành xử phù hợp: Xin written consent từ employer và bên liên quan trước khi chấp nhận arrangement.","Giữ bí mật vấn đề để không làm employer khó chịu"],"correct_option":1,"explanation":"IV(B): Nếu nhận benefit/compensation có thể compete hoặc conflict với lợi ích employer, cần **written consent từ tất cả bên liên quan** trước. Không đủ khi chỉ thông báo bằng miệng hay lấy phép khách hàng đơn phương. Vì thế cần giải quyết thực chất tình huống, thay vì dựa vào sự im lặng, tập quán thị trường hoặc lợi ích cá nhân."},{"id":"Q01-15","los_ids":["CFA26-10-03-LOS01"],"stem":"Đối với IV(C) Responsibilities of Supervisors, hành động nào phù hợp nhất?","options":["Giữ bí mật vấn đề để không làm employer khó chịu","Thực hiện tình huống này vì “mọi người đều làm”","Áp dụng cách hành xử phù hợp: Triển khai procedures phát hiện/phòng vi phạm, audit và hành động sửa khi có red flags."],"correct_option":2,"explanation":"IV(C): Supervisors phải có reasonable efforts để người dưới quyền tuân luật, regulations và Code/Standards, gồm effective compliance programs; giao toàn bộ trách nhiệm cho bộ phận khác không loại nghĩa vụ. Vì thế cần giải quyết thực chất tình huống, thay vì dựa vào sự im lặng, tập quán thị trường hoặc lợi ích cá nhân."},{"id":"Q01-16","los_ids":["CFA26-10-03-LOS01"],"stem":"Đối với V(A) Diligence and Reasonable Basis, hành động nào phù hợp nhất?","options":["Áp dụng cách hành xử phù hợp: Kiểm tra data, model assumptions, issuer information, downside risk và evidence phù hợp.","Giữ bí mật vấn đề để không làm employer khó chịu","Thực hiện tình huống này vì “mọi người đều làm”"],"correct_option":0,"explanation":"V(A): Research và recommendation cần thorough independent analysis với adequate basis; dùng third-party research phải đánh giá chất lượng methodology/data. Tin đồn không đủ làm cơ sở buy/sell. Vì thế cần giải quyết thực chất tình huống, thay vì dựa vào sự im lặng, tập quán thị trường hoặc lợi ích cá nhân."},{"id":"Q01-17","los_ids":["CFA26-10-03-LOS01"],"stem":"Đối với V(B) Communication with Clients and Prospective Clients, hành động nào phù hợp nhất?","options":["Thực hiện tình huống này vì “mọi người đều làm”","Áp dụng cách hành xử phù hợp: Trình bày phí rõ, risks, assumptions, model uncertainties và material changes cho client.","Giữ bí mật vấn đề để không làm employer khó chịu"],"correct_option":1,"explanation":"V(B): Phải disclose nature of services cùng related costs, methodology và material changes, important investment factors, significant limitations/risks, phân biệt facts và opinions. Không trình bày scenario như certainty. Vì thế cần giải quyết thực chất tình huống, thay vì dựa vào sự im lặng, tập quán thị trường hoặc lợi ích cá nhân."},{"id":"Q01-18","los_ids":["CFA26-10-03-LOS01"],"stem":"Đối với V(C) Record Retention, hành động nào phù hợp nhất?","options":["Giữ bí mật vấn đề để không làm employer khó chịu","Thực hiện tình huống này vì “mọi người đều làm”","Áp dụng cách hành xử phù hợp: Lưu data/model và versions đủ tái lập rationale; bàn giao records theo chính sách employer."],"correct_option":2,"explanation":"V(C): Tạo và duy trì records thích hợp cho investment analysis, recommendations và client communications. Thời hạn theo luật, regulation và firm policy; nếu thiếu, tham khảo guidance tương ứng và yêu cầu phù hợp. Vì thế cần giải quyết thực chất tình huống, thay vì dựa vào sự im lặng, tập quán thị trường hoặc lợi ích cá nhân."},{"id":"Q01-19","los_ids":["CFA26-10-03-LOS01"],"stem":"Đối với VI(A) Avoid or Disclose Conflicts, hành động nào phù hợp nhất?","options":["Áp dụng cách hành xử phù hợp: Avoid coverage nếu ảnh hưởng objectivity, hoặc disclose cụ thể holdings và implications rõ ràng.","Giữ bí mật vấn đề để không làm employer khó chịu","Thực hiện tình huống này vì “mọi người đều làm”"],"correct_option":0,"explanation":"VI(A): Ưu tiên avoid conflicts, nếu không thể tránh phải full and fair disclosure rõ ràng, nổi bật và dễ hiểu tới các bên liên quan; disclaimer mơ hồ ở cuối tài liệu chưa đủ. Một số conflicts cần từ chối hành động. Vì thế cần giải quyết thực chất tình huống, thay vì dựa vào sự im lặng, tập quán thị trường hoặc lợi ích cá nhân."},{"id":"Q01-20","los_ids":["CFA26-10-03-LOS01"],"stem":"Đối với VI(B) Priority of Transactions, hành động nào phù hợp nhất?","options":["Thực hiện tình huống này vì “mọi người đều làm”","Áp dụng cách hành xử phù hợp: Thực hiện client/employer transactions trước, tuân personal dealing restrictions.","Giữ bí mật vấn đề để không làm employer khó chịu"],"correct_option":1,"explanation":"VI(B): Giao dịch cho clients và employer phải ưu tiên trước personal beneficial ownership của member/candidate; không giao dịch trước clients để hưởng biến động do client order. Vì thế cần giải quyết thực chất tình huống, thay vì dựa vào sự im lặng, tập quán thị trường hoặc lợi ích cá nhân."},{"id":"Q01-21","los_ids":["CFA26-10-03-LOS01"],"stem":"Đối với VI(C) Referral Fees, hành động nào phù hợp nhất?","options":["Giữ bí mật vấn đề để không làm employer khó chịu","Thực hiện tình huống này vì “mọi người đều làm”","Áp dụng cách hành xử phù hợp: Nêu rõ bản chất và mức/ước lượng khoản referral compensation trước khi client quyết định."],"correct_option":2,"explanation":"VI(C): Disclosure cho employer, clients và prospective clients (as appropriate) về mọi lợi ích/fee nhận hoặc trả khi giới thiệu product/services, kể cả incentive noncash. Vì thế cần giải quyết thực chất tình huống, thay vì dựa vào sự im lặng, tập quán thị trường hoặc lợi ích cá nhân."},{"id":"Q01-22","los_ids":["CFA26-10-03-LOS01"],"stem":"Đối với VII(A) Conduct as Participants in CFA Institute Programs, hành động nào phù hợp nhất?","options":["Áp dụng cách hành xử phù hợp: Giữ bí mật exam content; có thể nêu nhận xét chung về trải nghiệm mà không tiết lộ nội dung bảo mật.","Giữ bí mật vấn đề để không làm employer khó chịu","Thực hiện tình huống này vì “mọi người đều làm”"],"correct_option":0,"explanation":"VII(A): Không hành xử làm ảnh hưởng integrity/reputation/security của CFA exams/programs; việc tiết lộ câu hỏi/nội dung cụ thể thuộc confidential exam information là violation, kể cả sau khi đã thi. Vì thế cần giải quyết thực chất tình huống, thay vì dựa vào sự im lặng, tập quán thị trường hoặc lợi ích cá nhân."},{"id":"Q01-23","los_ids":["CFA26-10-03-LOS01"],"stem":"Đối với VII(B) Reference to CFA Institute, CFA Designation, and CFA Program, hành động nào phù hợp nhất?","options":["Thực hiện tình huống này vì “mọi người đều làm”","Áp dụng cách hành xử phù hợp: Ghi đúng “passed Level I of CFA Program” khi thực sự qua, tránh claims performance guarantees.","Giữ bí mật vấn đề để không làm employer khó chịu"],"correct_option":1,"explanation":"VII(B): Không exaggerate ý nghĩa qualification/membership/candidacy, không hàm ý CFA Institute bảo đảm kết quả hoặc cấp mức Level I như designation. Dùng cách ghi trung thực về trạng thái đang học và kỳ thi đã qua. Vì thế cần giải quyết thực chất tình huống, thay vì dựa vào sự im lặng, tập quán thị trường hoặc lợi ích cá nhân."},{"id":"Q02-01","los_ids":["CFA26-10-03-LOS02"],"stem":"Cách phòng ngừa front-running hiệu quả nhất?","options":["Đề nghị trader tự hứa sẽ trung thực","Xóa trade logs sau mỗi tháng","Personal-trade pre-clearance và order timestamps"],"correct_option":2,"explanation":"Preclearance, restricted lists, timing logs và surveillance hỗ trợ thực thi VI(B), khác một lời hứa chung."},{"id":"Q02-02","los_ids":["CFA26-10-03-LOS02"],"stem":"Cách tốt nhất khi analyst nghiên cứu sản phẩm mới ngoài năng lực?","options":["Đào tạo, nhờ specialist và independent model review","Chỉ ghi disclaimer để tránh mọi trách nhiệm","Đưa ngay khuyến nghị"],"correct_option":0,"explanation":"I(E) đòi hỏi competence; disclosure không thay được chuyên môn cần thiết, nên cần đào tạo và kiểm định."},{"id":"Q02-03","los_ids":["CFA26-10-03-LOS02"],"stem":"Chương trình supervision hiệu quả nhất có?","options":["Chỉ họp hàng năm","Procedures, testing, escalation và remediation có bằng chứng","Chỉ manual dài"],"correct_option":1,"explanation":"IV(C) yêu cầu reasonable efforts giám sát và compliance procedures có khả năng phát hiện/phòng ngừa violations."},{"id":"Q03-01","los_ids":["CFA26-10-03-LOS03"],"stem":"Điều nào là dấu hiệu vi phạm I(A) Knowledge of the Law?","options":["Áp dụng biện pháp: Từ chối thực hiện, báo compliance, lưu quyết định, theo quy định pháp luật nghiêm ngặt hơn.","Thực hiện kiểm soát: Duy trì bảng cập nhật luật cho sản phẩm/jurisdiction; cơ chế hỏi legal counsel và báo cáo/dissociate khi phát hiện vi phạm.","Hành vi: Researcher được yêu cầu bán một tài sản bị cấm theo quy định sở tại dù Code không nhắc đến sản phẩm đó."],"correct_option":2,"explanation":"Tình huống đầu không phù hợp với I(A). Hành vi đúng và kiểm soát dự phòng nêu ở các phương án còn lại là hướng xử lý cần thiết theo chuẩn."},{"id":"Q03-02","los_ids":["CFA26-10-03-LOS03"],"stem":"Điều nào là dấu hiệu vi phạm I(B) Independence and Objectivity?","options":["Hành vi: Issuer trả toàn bộ kỳ nghỉ cao cấp để analyst đưa ra khuyến nghị mua, analyst chấp nhận và hứa nâng rating.","Áp dụng biện pháp: Từ chối hoặc xử lý theo chính sách independent research; để công ty kiểm soát gifts và phân tách bộ phận investment banking.","Thực hiện kiểm soát: Đặt ngưỡng quà tặng, approval, trả tiền di chuyển/khách sạn, firewall giữa research và transaction banking."],"correct_option":0,"explanation":"Tình huống đầu không phù hợp với I(B). Hành vi đúng và kiểm soát dự phòng nêu ở các phương án còn lại là hướng xử lý cần thiết theo chuẩn."},{"id":"Q03-03","los_ids":["CFA26-10-03-LOS03"],"stem":"Điều nào là dấu hiệu vi phạm I(C) Misrepresentation?","options":["Thực hiện kiểm soát: Checklist marketing/research, kiểm duyệt claim, lưu source citations và version controls.","Hành vi: Advisor tự nhận đã tạo model của đồng nghiệp và ghi “bảo đảm lợi nhuận 15% mỗi năm”.","Áp dụng biện pháp: Ghi nguồn rõ ràng, công bố assumptions, nhấn mạnh forecast không phải cam kết và xác minh dữ liệu."],"correct_option":1,"explanation":"Tình huống đầu không phù hợp với I(C). Hành vi đúng và kiểm soát dự phòng nêu ở các phương án còn lại là hướng xử lý cần thiết theo chuẩn."},{"id":"Q03-04","los_ids":["CFA26-10-03-LOS03"],"stem":"Điều nào là dấu hiệu vi phạm I(D) Misconduct?","options":["Áp dụng biện pháp: Không gian lận expense records, báo nội bộ khi cần và chịu trách nhiệm sửa sai.","Thực hiện kiểm soát: Segregation of duties, fraud reporting, review expense, escalation channels không trả đũa.","Hành vi: Portfolio manager sửa hóa đơn để nhận khoản hoàn trả chi phí không phát sinh."],"correct_option":2,"explanation":"Tình huống đầu không phù hợp với I(D). Hành vi đúng và kiểm soát dự phòng nêu ở các phương án còn lại là hướng xử lý cần thiết theo chuẩn."},{"id":"Q03-05","los_ids":["CFA26-10-03-LOS03"],"stem":"Điều nào là dấu hiệu vi phạm I(E) Competence?","options":["Hành vi: Analyst không hiểu cấu trúc path-dependent options nhưng vẫn công bố valuation “đã xác minh”.","Áp dụng biện pháp: Học/tham vấn chuyên môn, kiểm định pricing và nói rõ hạn chế trước khi khuyến nghị.","Thực hiện kiểm soát: Competency matrix theo vai trò, cập nhật năng lực thường xuyên, peer review models và đào tạo khi mở sản phẩm mới."],"correct_option":0,"explanation":"Tình huống đầu không phù hợp với I(E). Hành vi đúng và kiểm soát dự phòng nêu ở các phương án còn lại là hướng xử lý cần thiết theo chuẩn."},{"id":"Q03-06","los_ids":["CFA26-10-03-LOS03"],"stem":"Điều nào là dấu hiệu vi phạm II(A) Material Nonpublic Information?","options":["Thực hiện kiểm soát: Information barriers, restricted/watch lists, pre-clearance, confidentiality training và monitoring.","Hành vi: Analyst biết kết quả sáp nhập bí mật từ CFO và mua cổ phiếu trước thông báo.","Áp dụng biện pháp: Không giao dịch/gợi ý người khác; báo compliance, restricted list và chờ thông tin public được phổ biến."],"correct_option":1,"explanation":"Tình huống đầu không phù hợp với II(A). Hành vi đúng và kiểm soát dự phòng nêu ở các phương án còn lại là hướng xử lý cần thiết theo chuẩn."},{"id":"Q03-07","los_ids":["CFA26-10-03-LOS03"],"stem":"Điều nào là dấu hiệu vi phạm II(B) Market Manipulation?","options":["Áp dụng biện pháp: Giao dịch phản ánh nhu cầu thực và thông tin trung thực, không tạo tín hiệu order book giả.","Thực hiện kiểm soát: Trade surveillance, cấm spoofing/wash trading, review social-media market communication.","Hành vi: Trader đặt lệnh ảo lớn để tạo cảm giác demand cao rồi hủy trước khi khớp."],"correct_option":2,"explanation":"Tình huống đầu không phù hợp với II(B). Hành vi đúng và kiểm soát dự phòng nêu ở các phương án còn lại là hướng xử lý cần thiết theo chuẩn."},{"id":"Q03-08","los_ids":["CFA26-10-03-LOS03"],"stem":"Điều nào là dấu hiệu vi phạm III(A) Loyalty, Prudence, and Care?","options":["Hành vi: Manager chọn broker phí cao có liên quan cá nhân dù execution quality kém.","Áp dụng biện pháp: Đánh giá execution net of costs cho khách hàng, không ưu tiên affiliate nếu bất lợi.","Thực hiện kiểm soát: Best execution policies, conflict registry, kiểm tra fees/commissions, independent investment committee."],"correct_option":0,"explanation":"Tình huống đầu không phù hợp với III(A). Hành vi đúng và kiểm soát dự phòng nêu ở các phương án còn lại là hướng xử lý cần thiết theo chuẩn."},{"id":"Q03-09","los_ids":["CFA26-10-03-LOS03"],"stem":"Điều nào là dấu hiệu vi phạm III(B) Fair Dealing?","options":["Thực hiện kiểm soát: Pre-determined trade allocation policies, distribution lists, communication controls và periodic allocation audit.","Hành vi: Analyst gửi khuyến nghị mới cho nhóm bạn bè một ngày trước các khách hàng khác cùng loại dịch vụ.","Áp dụng biện pháp: Thiết lập phân phối đồng thời, trade allocation công bằng và có hồ sơ lý do nếu hạn chế thanh khoản."],"correct_option":1,"explanation":"Tình huống đầu không phù hợp với III(B). Hành vi đúng và kiểm soát dự phòng nêu ở các phương án còn lại là hướng xử lý cần thiết theo chuẩn."},{"id":"Q03-10","los_ids":["CFA26-10-03-LOS03"],"stem":"Điều nào là dấu hiệu vi phạm III(C) Suitability?","options":["Áp dụng biện pháp: Thu thập liquidity horizon/risk tolerance, đánh giá portfolio-level concentration, chỉ khuyến nghị phù hợp.","Thực hiện kiểm soát: Periodic IPS refresh, suitability forms, limits/concentration alerts và exceptions approval.","Hành vi: Advisor đặt 60% vốn hưu trí cho khách sắp nghỉ vào tài sản leveraged illiquid dù cần rút tiền năm tới."],"correct_option":2,"explanation":"Tình huống đầu không phù hợp với III(C). Hành vi đúng và kiểm soát dự phòng nêu ở các phương án còn lại là hướng xử lý cần thiết theo chuẩn."},{"id":"Q03-11","los_ids":["CFA26-10-03-LOS03"],"stem":"Điều nào là dấu hiệu vi phạm III(D) Performance Presentation?","options":["Hành vi: Manager giới thiệu “5 năm lợi nhuận cao” nhưng chỉ chọn tài khoản thắng lớn, bỏ tất cả tài khoản lỗ.","Áp dụng biện pháp: Công bố phương pháp, time windows nhất quán, nêu limitations và số liệu đầy đủ, rõ gross/net.","Thực hiện kiểm soát: Performance data controls, standardized reporting periods, performance reconciliation và independent review."],"correct_option":0,"explanation":"Tình huống đầu không phù hợp với III(D). Hành vi đúng và kiểm soát dự phòng nêu ở các phương án còn lại là hướng xử lý cần thiết theo chuẩn."},{"id":"Q03-12","los_ids":["CFA26-10-03-LOS03"],"stem":"Điều nào là dấu hiệu vi phạm III(E) Preservation of Confidentiality?","options":["Thực hiện kiểm soát: Role-based access, encryption, written consent, documented disclosure exceptions và privacy controls.","Hành vi: Advisor chuyển danh sách khách VIP cho người quen làm bảo hiểm dù chưa có đồng ý.","Áp dụng biện pháp: Chỉ chia sẻ trong phạm vi được phép hoặc theo legal requirement, bảo vệ file và access."],"correct_option":1,"explanation":"Tình huống đầu không phù hợp với III(E). Hành vi đúng và kiểm soát dự phòng nêu ở các phương án còn lại là hướng xử lý cần thiết theo chuẩn."},{"id":"Q03-13","los_ids":["CFA26-10-03-LOS03"],"stem":"Điều nào là dấu hiệu vi phạm IV(A) Loyalty?","options":["Áp dụng biện pháp: Giữ bí mật, tuân hợp đồng, chỉ dùng thông tin public/mối quan hệ hợp pháp sau nghỉ.","Thực hiện kiểm soát: Clear exit procedures, confidentiality notices, access revocation, noncompete rules theo luật.","Hành vi: Employee tải về toàn bộ client list mật rồi chuyển sang competitor trước ngày nghỉ."],"correct_option":2,"explanation":"Tình huống đầu không phù hợp với IV(A). Hành vi đúng và kiểm soát dự phòng nêu ở các phương án còn lại là hướng xử lý cần thiết theo chuẩn."},{"id":"Q03-14","los_ids":["CFA26-10-03-LOS03"],"stem":"Điều nào là dấu hiệu vi phạm IV(B) Additional Compensation Arrangements?","options":["Hành vi: Manager nhận bonus riêng từ client nếu vượt index nhưng không xin phép employer.","Áp dụng biện pháp: Xin written consent từ employer và bên liên quan trước khi chấp nhận arrangement.","Thực hiện kiểm soát: Written pre-approval form, registry outside compensation, disclosure review và record retention."],"correct_option":0,"explanation":"Tình huống đầu không phù hợp với IV(B). Hành vi đúng và kiểm soát dự phòng nêu ở các phương án còn lại là hướng xử lý cần thiết theo chuẩn."},{"id":"Q03-15","los_ids":["CFA26-10-03-LOS03"],"stem":"Điều nào là dấu hiệu vi phạm IV(C) Responsibilities of Supervisors?","options":["Thực hiện kiểm soát: Written supervision map, regular sampling review, training, escalation and remediation logs.","Hành vi: Team leader biết research analysts bị pressure viết báo cáo giả nhưng không thiết lập review hay xử lý.","Áp dụng biện pháp: Triển khai procedures phát hiện/phòng vi phạm, audit và hành động sửa khi có red flags."],"correct_option":1,"explanation":"Tình huống đầu không phù hợp với IV(C). Hành vi đúng và kiểm soát dự phòng nêu ở các phương án còn lại là hướng xử lý cần thiết theo chuẩn."},{"id":"Q03-16","los_ids":["CFA26-10-03-LOS03"],"stem":"Điều nào là dấu hiệu vi phạm V(A) Diligence and Reasonable Basis?","options":["Áp dụng biện pháp: Kiểm tra data, model assumptions, issuer information, downside risk và evidence phù hợp.","Thực hiện kiểm soát: Research sign-off, independent model validation, data/vendor due diligence và change logs.","Hành vi: Analyst upgrade stock vì một bài đăng ẩn danh không kiểm chứng trên mạng xã hội."],"correct_option":2,"explanation":"Tình huống đầu không phù hợp với V(A). Hành vi đúng và kiểm soát dự phòng nêu ở các phương án còn lại là hướng xử lý cần thiết theo chuẩn."},{"id":"Q03-17","los_ids":["CFA26-10-03-LOS03"],"stem":"Điều nào là dấu hiệu vi phạm V(B) Communication with Clients and Prospective Clients?","options":["Hành vi: Adviser bán strategy phí cao nhưng che management/exit fees và cam kết return dự phóng như thực tế.","Áp dụng biện pháp: Trình bày phí rõ, risks, assumptions, model uncertainties và material changes cho client.","Thực hiện kiểm soát: Standardized fee and risk disclosure, fact/opinion labels, review of client materials và update notice."],"correct_option":0,"explanation":"Tình huống đầu không phù hợp với V(B). Hành vi đúng và kiểm soát dự phòng nêu ở các phương án còn lại là hướng xử lý cần thiết theo chuẩn."},{"id":"Q03-18","los_ids":["CFA26-10-03-LOS03"],"stem":"Điều nào là dấu hiệu vi phạm V(C) Record Retention?","options":["Thực hiện kiểm soát: Document-management retention rules, approved repositories, audit trails, periodic access/retrieval tests.","Hành vi: Analyst xóa toàn bộ supporting model sau khi khách hàng đầu tư, không thể chứng minh thesis.","Áp dụng biện pháp: Lưu data/model và versions đủ tái lập rationale; bàn giao records theo chính sách employer."],"correct_option":1,"explanation":"Tình huống đầu không phù hợp với V(C). Hành vi đúng và kiểm soát dự phòng nêu ở các phương án còn lại là hướng xử lý cần thiết theo chuẩn."},{"id":"Q03-19","los_ids":["CFA26-10-03-LOS03"],"stem":"Điều nào là dấu hiệu vi phạm VI(A) Avoid or Disclose Conflicts?","options":["Áp dụng biện pháp: Avoid coverage nếu ảnh hưởng objectivity, hoặc disclose cụ thể holdings và implications rõ ràng.","Thực hiện kiểm soát: Conflicts inventory, pre-approval, prominent client disclosures, independent oversight.","Hành vi: Analyst sở hữu lượng lớn cổ phiếu đang khuyến nghị mua mà chỉ ghi “có thể có lợi ích”."],"correct_option":2,"explanation":"Tình huống đầu không phù hợp với VI(A). Hành vi đúng và kiểm soát dự phòng nêu ở các phương án còn lại là hướng xử lý cần thiết theo chuẩn."},{"id":"Q03-20","los_ids":["CFA26-10-03-LOS03"],"stem":"Điều nào là dấu hiệu vi phạm VI(B) Priority of Transactions?","options":["Hành vi: Trader mua trước cho tài khoản cá nhân ngay khi biết lệnh mua lớn của client sẽ được thực hiện.","Áp dụng biện pháp: Thực hiện client/employer transactions trước, tuân personal dealing restrictions.","Thực hiện kiểm soát: Personal-trade preclearance, restricted list, order time-stamps và surveillance."],"correct_option":0,"explanation":"Tình huống đầu không phù hợp với VI(B). Hành vi đúng và kiểm soát dự phòng nêu ở các phương án còn lại là hướng xử lý cần thiết theo chuẩn."},{"id":"Q03-21","los_ids":["CFA26-10-03-LOS03"],"stem":"Điều nào là dấu hiệu vi phạm VI(C) Referral Fees?","options":["Thực hiện kiểm soát: Referral agreement inventory, standardized referral disclosures, conflict review.","Hành vi: Advisor giới thiệu một manager và nhận 1% assets mà không disclosure cho khách.","Áp dụng biện pháp: Nêu rõ bản chất và mức/ước lượng khoản referral compensation trước khi client quyết định."],"correct_option":1,"explanation":"Tình huống đầu không phù hợp với VI(C). Hành vi đúng và kiểm soát dự phòng nêu ở các phương án còn lại là hướng xử lý cần thiết theo chuẩn."},{"id":"Q03-22","los_ids":["CFA26-10-03-LOS03"],"stem":"Điều nào là dấu hiệu vi phạm VII(A) Conduct as Participants in CFA Institute Programs?","options":["Áp dụng biện pháp: Giữ bí mật exam content; có thể nêu nhận xét chung về trải nghiệm mà không tiết lộ nội dung bảo mật.","Thực hiện kiểm soát: Exam confidentiality training, social-media rules và reporting channels.","Hành vi: Candidate đăng các câu và đáp án cụ thể vừa gặp ở exam lên nhóm chat."],"correct_option":2,"explanation":"Tình huống đầu không phù hợp với VII(A). Hành vi đúng và kiểm soát dự phòng nêu ở các phương án còn lại là hướng xử lý cần thiết theo chuẩn."},{"id":"Q03-23","los_ids":["CFA26-10-03-LOS03"],"stem":"Điều nào là dấu hiệu vi phạm VII(B) Reference to CFA Institute, CFA Designation, and CFA Program?","options":["Hành vi: Candidate ghi “CFA Level I certified expert, CFA guarantees 20% annual returns”.","Áp dụng biện pháp: Ghi đúng “passed Level I of CFA Program” khi thực sự qua, tránh claims performance guarantees.","Thực hiện kiểm soát: Review job titles/marketing, standardized credential wording và periodic public-profile audit."],"correct_option":0,"explanation":"Tình huống đầu không phù hợp với VII(B). Hành vi đúng và kiểm soát dự phòng nêu ở các phương án còn lại là hướng xử lý cần thiết theo chuẩn."}],"flashcards":[{"id":"C01-01","los_ids":["CFA26-10-03-LOS01"],"front":"I(A) Knowledge of the Law: nội dung và phạm vi — nêu cách xử lý?","back":"Khi làm việc ở nhiều jurisdiction, phải xác định applicable laws/rules, CFA Code/Standards và áp dụng mức nghiêm ngặt hơn khi có khác biệt. Không được knowingly assist violation; phải dissociate khỏi hành vi sai. Để phân loại tình huống phải xác định quan hệ giữa analyst/manager, client, employer, thông tin công khai và thực chất hành vi. Ví dụ rủi ro: Researcher được yêu cầu bán một tài sản bị cấm theo quy định sở tại dù Code không nhắc đến sản phẩm đó. Cách xử lý phù hợp: Từ chối thực hiện, báo compliance, lưu quyết định, theo quy định pháp luật nghiêm ngặt hơn."},{"id":"C01-02","los_ids":["CFA26-10-03-LOS01"],"front":"I(B) Independence and Objectivity: nội dung và phạm vi — nêu cách xử lý?","back":"Giữ independent professional judgment trước quà tặng, hospitality, travel, investment-banking pressure hay bên bán nghiên cứu. Giá trị quà có thể ảnh hưởng tính khách quan; disclosure không luôn chữa được ảnh hưởng thực chất. Để phân loại tình huống phải xác định quan hệ giữa analyst/manager, client, employer, thông tin công khai và thực chất hành vi. Ví dụ rủi ro: Issuer trả toàn bộ kỳ nghỉ cao cấp để analyst đưa ra khuyến nghị mua, analyst chấp nhận và hứa nâng rating. Cách xử lý phù hợp: Từ chối hoặc xử lý theo chính sách independent research; để công ty kiểm soát gifts và phân tách bộ phận investment banking."},{"id":"C01-03","los_ids":["CFA26-10-03-LOS01"],"front":"I(C) Misrepresentation: nội dung và phạm vi — nêu cách xử lý?","back":"Không cố tình trình bày sai phương pháp, credentials, track record, forecast là fact, hoặc dùng tài liệu của người khác không ghi nguồn. Không dùng charts chọn kỳ thuận lợi để tạo ấn tượng sai lệch. Để phân loại tình huống phải xác định quan hệ giữa analyst/manager, client, employer, thông tin công khai và thực chất hành vi. Ví dụ rủi ro: Advisor tự nhận đã tạo model của đồng nghiệp và ghi “bảo đảm lợi nhuận 15% mỗi năm”. Cách xử lý phù hợp: Ghi nguồn rõ ràng, công bố assumptions, nhấn mạnh forecast không phải cam kết và xác minh dữ liệu."},{"id":"C01-04","los_ids":["CFA26-10-03-LOS01"],"front":"I(D) Misconduct: nội dung và phạm vi — nêu cách xử lý?","back":"Cấm hành vi nghề nghiệp dishonesty, fraud, deceit hoặc hành vi phản ánh bất lợi tới reputation, integrity và competence. Không phải mọi vi phạm luật riêng tư đều tự động là professional misconduct, cần xét tính liên quan và facts. Để phân loại tình huống phải xác định quan hệ giữa analyst/manager, client, employer, thông tin công khai và thực chất hành vi. Ví dụ rủi ro: Portfolio manager sửa hóa đơn để nhận khoản hoàn trả chi phí không phát sinh. Cách xử lý phù hợp: Không gian lận expense records, báo nội bộ khi cần và chịu trách nhiệm sửa sai."},{"id":"C01-05","los_ids":["CFA26-10-03-LOS01"],"front":"I(E) Competence: nội dung và phạm vi — nêu cách xử lý?","back":"Phải có và duy trì năng lực thực tế cần thiết cho nhiệm vụ chuyên môn; không nhất thiết có một số giờ continuing education cố định cho mọi công việc. Khi chuyển sản phẩm phức tạp phải học hoặc tìm chuyên gia. Để phân loại tình huống phải xác định quan hệ giữa analyst/manager, client, employer, thông tin công khai và thực chất hành vi. Ví dụ rủi ro: Analyst không hiểu cấu trúc path-dependent options nhưng vẫn công bố valuation “đã xác minh”. Cách xử lý phù hợp: Học/tham vấn chuyên môn, kiểm định pricing và nói rõ hạn chế trước khi khuyến nghị."},{"id":"C01-06","los_ids":["CFA26-10-03-LOS01"],"front":"II(A) Material Nonpublic Information: nội dung và phạm vi — nêu cách xử lý?","back":"Người nắm material nonpublic information có thể ảnh hưởng giá đầu tư không được trading hoặc khiến người khác trading trên thông tin đó. Mosaic theory cho phép public plus nonmaterial nonpublic info được phân tích hợp pháp. Để phân loại tình huống phải xác định quan hệ giữa analyst/manager, client, employer, thông tin công khai và thực chất hành vi. Ví dụ rủi ro: Analyst biết kết quả sáp nhập bí mật từ CFO và mua cổ phiếu trước thông báo. Cách xử lý phù hợp: Không giao dịch/gợi ý người khác; báo compliance, restricted list và chờ thông tin public được phổ biến."},{"id":"C01-07","los_ids":["CFA26-10-03-LOS01"],"front":"II(B) Market Manipulation: nội dung và phạm vi — nêu cách xử lý?","back":"Cấm hành vi bóp méo prices hoặc làm tăng volume giả tạo với intent gây hiểu nhầm. Giao dịch hợp pháp dựa trên phân tích thực khác với spoofing, wash trades hoặc tin giả nhằm thao túng. Để phân loại tình huống phải xác định quan hệ giữa analyst/manager, client, employer, thông tin công khai và thực chất hành vi. Ví dụ rủi ro: Trader đặt lệnh ảo lớn để tạo cảm giác demand cao rồi hủy trước khi khớp. Cách xử lý phù hợp: Giao dịch phản ánh nhu cầu thực và thông tin trung thực, không tạo tín hiệu order book giả."},{"id":"C01-08","los_ids":["CFA26-10-03-LOS01"],"front":"III(A) Loyalty, Prudence, and Care: nội dung và phạm vi — nêu cách xử lý?","back":"Trong nhiệm vụ với khách hàng, đặt lợi ích clients lên trước employer và bản thân; xử lý tài sản được ủy thác cẩn trọng, không làm lợi công ty bằng fees không minh bạch hoặc giao dịch bất lợi. Để phân loại tình huống phải xác định quan hệ giữa analyst/manager, client, employer, thông tin công khai và thực chất hành vi. Ví dụ rủi ro: Manager chọn broker phí cao có liên quan cá nhân dù execution quality kém. Cách xử lý phù hợp: Đánh giá execution net of costs cho khách hàng, không ưu tiên affiliate nếu bất lợi."},{"id":"C02-01","los_ids":["CFA26-10-03-LOS02"],"front":"I(A) — thiết kế kiểm soát phòng ngừa — nêu cách xử lý?","back":"Đối với I(A) Knowledge of the Law, hệ thống kiểm soát phải đi từ nhận diện nguồn rủi ro đến hành động khắc phục và lưu dấu vết: Duy trì bảng cập nhật luật cho sản phẩm/jurisdiction; cơ chế hỏi legal counsel và báo cáo/dissociate khi phát hiện vi phạm. Một quy trình chỉ hiệu quả khi người chịu trách nhiệm, thời điểm kiểm tra và cơ chế escalation được xác định rõ, không chỉ ghi “tuân thủ quy định” chung chung."},{"id":"C02-02","los_ids":["CFA26-10-03-LOS02"],"front":"I(B) — thiết kế kiểm soát phòng ngừa — nêu cách xử lý?","back":"Đối với I(B) Independence and Objectivity, hệ thống kiểm soát phải đi từ nhận diện nguồn rủi ro đến hành động khắc phục và lưu dấu vết: Đặt ngưỡng quà tặng, approval, trả tiền di chuyển/khách sạn, firewall giữa research và transaction banking. Một quy trình chỉ hiệu quả khi người chịu trách nhiệm, thời điểm kiểm tra và cơ chế escalation được xác định rõ, không chỉ ghi “tuân thủ quy định” chung chung."},{"id":"C02-03","los_ids":["CFA26-10-03-LOS02"],"front":"I(C) — thiết kế kiểm soát phòng ngừa — nêu cách xử lý?","back":"Đối với I(C) Misrepresentation, hệ thống kiểm soát phải đi từ nhận diện nguồn rủi ro đến hành động khắc phục và lưu dấu vết: Checklist marketing/research, kiểm duyệt claim, lưu source citations và version controls. Một quy trình chỉ hiệu quả khi người chịu trách nhiệm, thời điểm kiểm tra và cơ chế escalation được xác định rõ, không chỉ ghi “tuân thủ quy định” chung chung."},{"id":"C02-04","los_ids":["CFA26-10-03-LOS02"],"front":"I(D) — thiết kế kiểm soát phòng ngừa — nêu cách xử lý?","back":"Đối với I(D) Misconduct, hệ thống kiểm soát phải đi từ nhận diện nguồn rủi ro đến hành động khắc phục và lưu dấu vết: Segregation of duties, fraud reporting, review expense, escalation channels không trả đũa. Một quy trình chỉ hiệu quả khi người chịu trách nhiệm, thời điểm kiểm tra và cơ chế escalation được xác định rõ, không chỉ ghi “tuân thủ quy định” chung chung."},{"id":"C02-05","los_ids":["CFA26-10-03-LOS02"],"front":"I(E) — thiết kế kiểm soát phòng ngừa — nêu cách xử lý?","back":"Đối với I(E) Competence, hệ thống kiểm soát phải đi từ nhận diện nguồn rủi ro đến hành động khắc phục và lưu dấu vết: Competency matrix theo vai trò, cập nhật năng lực thường xuyên, peer review models và đào tạo khi mở sản phẩm mới. Một quy trình chỉ hiệu quả khi người chịu trách nhiệm, thời điểm kiểm tra và cơ chế escalation được xác định rõ, không chỉ ghi “tuân thủ quy định” chung chung."},{"id":"C02-06","los_ids":["CFA26-10-03-LOS02"],"front":"II(A) — thiết kế kiểm soát phòng ngừa — nêu cách xử lý?","back":"Đối với II(A) Material Nonpublic Information, hệ thống kiểm soát phải đi từ nhận diện nguồn rủi ro đến hành động khắc phục và lưu dấu vết: Information barriers, restricted/watch lists, pre-clearance, confidentiality training và monitoring. Một quy trình chỉ hiệu quả khi người chịu trách nhiệm, thời điểm kiểm tra và cơ chế escalation được xác định rõ, không chỉ ghi “tuân thủ quy định” chung chung."},{"id":"C02-07","los_ids":["CFA26-10-03-LOS02"],"front":"II(B) — thiết kế kiểm soát phòng ngừa — nêu cách xử lý?","back":"Đối với II(B) Market Manipulation, hệ thống kiểm soát phải đi từ nhận diện nguồn rủi ro đến hành động khắc phục và lưu dấu vết: Trade surveillance, cấm spoofing/wash trading, review social-media market communication. Một quy trình chỉ hiệu quả khi người chịu trách nhiệm, thời điểm kiểm tra và cơ chế escalation được xác định rõ, không chỉ ghi “tuân thủ quy định” chung chung."},{"id":"C02-08","los_ids":["CFA26-10-03-LOS02"],"front":"III(A) — thiết kế kiểm soát phòng ngừa — nêu cách xử lý?","back":"Đối với III(A) Loyalty, Prudence, and Care, hệ thống kiểm soát phải đi từ nhận diện nguồn rủi ro đến hành động khắc phục và lưu dấu vết: Best execution policies, conflict registry, kiểm tra fees/commissions, independent investment committee. Một quy trình chỉ hiệu quả khi người chịu trách nhiệm, thời điểm kiểm tra và cơ chế escalation được xác định rõ, không chỉ ghi “tuân thủ quy định” chung chung."},{"id":"C03-01","los_ids":["CFA26-10-03-LOS03"],"front":"I(A) — phân biệt conforming và violating conduct — nêu cách xử lý?","back":"Tình huống vi phạm I(A): Researcher được yêu cầu bán một tài sản bị cấm theo quy định sở tại dù Code không nhắc đến sản phẩm đó. Hành vi đáp ứng chuẩn cần là: Từ chối thực hiện, báo compliance, lưu quyết định, theo quy định pháp luật nghiêm ngặt hơn. Khi làm câu CFA phải đọc facts về thời điểm, consent, mức disclosure và consequences; cùng một sản phẩm/tin tức có thể có kết luận khác nếu các tình tiết cốt lõi thay đổi."},{"id":"C03-02","los_ids":["CFA26-10-03-LOS03"],"front":"I(B) — phân biệt conforming và violating conduct — nêu cách xử lý?","back":"Tình huống vi phạm I(B): Issuer trả toàn bộ kỳ nghỉ cao cấp để analyst đưa ra khuyến nghị mua, analyst chấp nhận và hứa nâng rating. Hành vi đáp ứng chuẩn cần là: Từ chối hoặc xử lý theo chính sách independent research; để công ty kiểm soát gifts và phân tách bộ phận investment banking. Khi làm câu CFA phải đọc facts về thời điểm, consent, mức disclosure và consequences; cùng một sản phẩm/tin tức có thể có kết luận khác nếu các tình tiết cốt lõi thay đổi."},{"id":"C03-03","los_ids":["CFA26-10-03-LOS03"],"front":"I(C) — phân biệt conforming và violating conduct — nêu cách xử lý?","back":"Tình huống vi phạm I(C): Advisor tự nhận đã tạo model của đồng nghiệp và ghi “bảo đảm lợi nhuận 15% mỗi năm”. Hành vi đáp ứng chuẩn cần là: Ghi nguồn rõ ràng, công bố assumptions, nhấn mạnh forecast không phải cam kết và xác minh dữ liệu. Khi làm câu CFA phải đọc facts về thời điểm, consent, mức disclosure và consequences; cùng một sản phẩm/tin tức có thể có kết luận khác nếu các tình tiết cốt lõi thay đổi."},{"id":"C03-04","los_ids":["CFA26-10-03-LOS03"],"front":"I(D) — phân biệt conforming và violating conduct — nêu cách xử lý?","back":"Tình huống vi phạm I(D): Portfolio manager sửa hóa đơn để nhận khoản hoàn trả chi phí không phát sinh. Hành vi đáp ứng chuẩn cần là: Không gian lận expense records, báo nội bộ khi cần và chịu trách nhiệm sửa sai. Khi làm câu CFA phải đọc facts về thời điểm, consent, mức disclosure và consequences; cùng một sản phẩm/tin tức có thể có kết luận khác nếu các tình tiết cốt lõi thay đổi."},{"id":"C03-05","los_ids":["CFA26-10-03-LOS03"],"front":"I(E) — phân biệt conforming và violating conduct — nêu cách xử lý?","back":"Tình huống vi phạm I(E): Analyst không hiểu cấu trúc path-dependent options nhưng vẫn công bố valuation “đã xác minh”. Hành vi đáp ứng chuẩn cần là: Học/tham vấn chuyên môn, kiểm định pricing và nói rõ hạn chế trước khi khuyến nghị. Khi làm câu CFA phải đọc facts về thời điểm, consent, mức disclosure và consequences; cùng một sản phẩm/tin tức có thể có kết luận khác nếu các tình tiết cốt lõi thay đổi."},{"id":"C03-06","los_ids":["CFA26-10-03-LOS03"],"front":"II(A) — phân biệt conforming và violating conduct — nêu cách xử lý?","back":"Tình huống vi phạm II(A): Analyst biết kết quả sáp nhập bí mật từ CFO và mua cổ phiếu trước thông báo. Hành vi đáp ứng chuẩn cần là: Không giao dịch/gợi ý người khác; báo compliance, restricted list và chờ thông tin public được phổ biến. Khi làm câu CFA phải đọc facts về thời điểm, consent, mức disclosure và consequences; cùng một sản phẩm/tin tức có thể có kết luận khác nếu các tình tiết cốt lõi thay đổi."},{"id":"C03-07","los_ids":["CFA26-10-03-LOS03"],"front":"II(B) — phân biệt conforming và violating conduct — nêu cách xử lý?","back":"Tình huống vi phạm II(B): Trader đặt lệnh ảo lớn để tạo cảm giác demand cao rồi hủy trước khi khớp. Hành vi đáp ứng chuẩn cần là: Giao dịch phản ánh nhu cầu thực và thông tin trung thực, không tạo tín hiệu order book giả. Khi làm câu CFA phải đọc facts về thời điểm, consent, mức disclosure và consequences; cùng một sản phẩm/tin tức có thể có kết luận khác nếu các tình tiết cốt lõi thay đổi."},{"id":"C03-08","los_ids":["CFA26-10-03-LOS03"],"front":"III(A) — phân biệt conforming và violating conduct — nêu cách xử lý?","back":"Tình huống vi phạm III(A): Manager chọn broker phí cao có liên quan cá nhân dù execution quality kém. Hành vi đáp ứng chuẩn cần là: Đánh giá execution net of costs cho khách hàng, không ưu tiên affiliate nếu bất lợi. Khi làm câu CFA phải đọc facts về thời điểm, consent, mức disclosure và consequences; cùng một sản phẩm/tin tức có thể có kết luận khác nếu các tình tiết cốt lõi thay đổi."}],"review_status":"targeted_los_source_scenario_and_browser_QA_pass_not_exhaustive_all_PDFs"},{"module_id":"CFA26-10-04","title":"Introduction to the Global Investment Performance Standards (GIPS)","version":"2026","source_basis":[{"source_id":"CFAI_2026","pdf_pages":[255,264],"relation":"primary"},{"source_id":"Kaplan_2026","pdf_pages":[195,200],"relation":"supplementary"},{"source_id":"SAPP_2026","pdf_pages":[201,223],"relation":"supplementary"}],"los_coverage":[{"los_id":"CFA26-10-04-LOS01","learning_goal_vi":"Giải thích lý do GIPS được tạo, ai claim compliance và ai hưởng lợi.","status":"targeted_CFAI_Kaplan_SAPP_scenarios_QA_pass","competency_criteria":["Mọi Standard I–VII hoặc GIPS topics cần có nội dung liên quan","Phân tích facts, exception, compliance controls và cách nhận biết hành vi sai","2+ original cases và 3+ câu trắc nghiệm có lời giải, được kiểm tra theo nguồn phù hợp"],"concept_ids":["S01-01","S01-02","S01-03","S01-04"],"formula_ids":["F01-01"],"example_ids":["E01-01","E01-02"],"question_ids":["Q01-01","Q01-02","Q01-03"],"source_anchor_pages":{"CFAI_2026":{"file":"2026_CFA_L1V10_Ethics_ONLINE.pdf","pdf_page":256},"Kaplan_2026":{"file":"Kaplan SchweserNotes Book4.pdf","pdf_page":195},"SAPP_2026":{"file":"SAPP Ethics.pdf","pdf_page":202}},"missing_items":[]},{"los_id":"CFA26-10-04-LOS02","learning_goal_vi":"Mô tả những khái niệm then chốt trong GIPS Standards for Firms.","status":"targeted_CFAI_Kaplan_SAPP_scenarios_QA_pass","competency_criteria":["Mọi Standard I–VII hoặc GIPS topics cần có nội dung liên quan","Phân tích facts, exception, compliance controls và cách nhận biết hành vi sai","2+ original cases và 3+ câu trắc nghiệm có lời giải, được kiểm tra theo nguồn phù hợp"],"concept_ids":["S02-01","S02-02","S02-03","S02-04"],"formula_ids":["F02-01"],"example_ids":["E02-01","E02-02"],"question_ids":["Q02-01","Q02-02","Q02-03"],"source_anchor_pages":{"CFAI_2026":{"file":"2026_CFA_L1V10_Ethics_ONLINE.pdf","pdf_page":257},"Kaplan_2026":{"file":"Kaplan SchweserNotes Book4.pdf","pdf_page":195},"SAPP_2026":{"file":"SAPP Ethics.pdf","pdf_page":211}},"missing_items":[]},{"los_id":"CFA26-10-04-LOS03","learning_goal_vi":"Giải thích mục đích composites trong performance reporting.","status":"targeted_CFAI_Kaplan_SAPP_scenarios_QA_pass","competency_criteria":["Mọi Standard I–VII hoặc GIPS topics cần có nội dung liên quan","Phân tích facts, exception, compliance controls và cách nhận biết hành vi sai","2+ original cases và 3+ câu trắc nghiệm có lời giải, được kiểm tra theo nguồn phù hợp"],"concept_ids":["S03-01","S03-02","S03-03","S03-04"],"formula_ids":["F03-01"],"example_ids":["E03-01","E03-02"],"question_ids":["Q03-01","Q03-02","Q03-03"],"source_anchor_pages":{"CFAI_2026":{"file":"2026_CFA_L1V10_Ethics_ONLINE.pdf","pdf_page":258},"Kaplan_2026":{"file":"Kaplan SchweserNotes Book4.pdf","pdf_page":196},"SAPP_2026":{"file":"SAPP Ethics.pdf","pdf_page":212}},"missing_items":[]},{"los_id":"CFA26-10-04-LOS04","learning_goal_vi":"Mô tả fundamentals of compliance, firm definition và discretion.","status":"targeted_CFAI_Kaplan_SAPP_scenarios_QA_pass","competency_criteria":["Mọi Standard I–VII hoặc GIPS topics cần có nội dung liên quan","Phân tích facts, exception, compliance controls và cách nhận biết hành vi sai","2+ original cases và 3+ câu trắc nghiệm có lời giải, được kiểm tra theo nguồn phù hợp"],"concept_ids":["S04-01","S04-02","S04-03","S04-04","S04-05"],"formula_ids":["F04-01"],"example_ids":["E04-01","E04-02"],"question_ids":["Q04-01","Q04-02","Q04-03"],"source_anchor_pages":{"CFAI_2026":{"file":"2026_CFA_L1V10_Ethics_ONLINE.pdf","pdf_page":259},"Kaplan_2026":{"file":"Kaplan SchweserNotes Book4.pdf","pdf_page":196},"SAPP_2026":{"file":"SAPP Ethics.pdf","pdf_page":215}},"missing_items":[]},{"los_id":"CFA26-10-04-LOS05","learning_goal_vi":"Mô tả independent verification và ý nghĩa của verification.","status":"targeted_CFAI_Kaplan_SAPP_scenarios_QA_pass","competency_criteria":["Mọi Standard I–VII hoặc GIPS topics cần có nội dung liên quan","Phân tích facts, exception, compliance controls và cách nhận biết hành vi sai","2+ original cases và 3+ câu trắc nghiệm có lời giải, được kiểm tra theo nguồn phù hợp"],"concept_ids":["S05-01","S05-02","S05-03","S05-04"],"formula_ids":["F05-01"],"example_ids":["E05-01","E05-02"],"question_ids":["Q05-01","Q05-02","Q05-03"],"source_anchor_pages":{"CFAI_2026":{"file":"2026_CFA_L1V10_Ethics_ONLINE.pdf","pdf_page":260},"Kaplan_2026":{"file":"Kaplan SchweserNotes Book4.pdf","pdf_page":197},"SAPP_2026":{"file":"SAPP Ethics.pdf","pdf_page":222}},"missing_items":[]}],"sections":[{"id":"S01-01","los_ids":["CFA26-10-04-LOS01"],"heading_vi":"Mục đích của GIPS","body_vi":"GIPS (Global Investment Performance Standards) nhằm thúc đẩy trình bày track record công bằng, minh bạch, nhất quán và có thể so sánh xuyên manager/markets. Trước khi có chuẩn, các cách cherry-picking winner accounts, survivorship bias và thay kỳ báo cáo tùy ý khiến khách hàng khó đánh giá năng lực quản lý thực."},{"id":"S01-02","los_ids":["CFA26-10-04-LOS01"],"heading_vi":"Ai có thể claim compliance","body_vi":"Các firms quản lý tài sản cạnh tranh để nhận investment management business có thể claim compliance với GIPS Standards for Firms khi đáp ứng mọi applicable requirements. Asset owners có GIPS Standards for Asset Owners riêng. Một portfolio hoặc composite đơn lẻ không tự xưng tuân thủ thay cho cả firm."},{"id":"S01-03","los_ids":["CFA26-10-04-LOS01"],"heading_vi":"Lợi ích cho nhà đầu tư và firms","body_vi":"Prospective clients có phương pháp so sánh performance rõ hơn; firms có reporting disciplines, data controls và credibility. Standards khuyến khích fair competition nhưng không bảo đảm một manager outperform benchmark hoặc không có risk."},{"id":"S01-04","los_ids":["CFA26-10-04-LOS01"],"heading_vi":"Các điều không đúng","body_vi":"GIPS nhìn chung không tự động bắt buộc theo luật ở mọi jurisdiction và không phải chứng chỉ do CFA Institute trao cho từng chiến lược. Một firm có thể tự claim tuân thủ nếu thực sự đáp ứng quy định, còn verification là quy trình đánh giá độc lập được khuyến khích."},{"id":"S02-01","los_ids":["CFA26-10-04-LOS02"],"heading_vi":"Fair representation và full disclosure","body_vi":"GIPS đòi hỏi returns được tính/diễn giải nhất quán, report phù hợp với prescribed methodology và cung cấp disclosures làm rõ assumptions, fees, composites, benchmarks. Không chọn những account và period làm performance trông đẹp hơn."},{"id":"S02-02","los_ids":["CFA26-10-04-LOS02"],"heading_vi":"Firm, composite và discretion","body_vi":"GIPS Standards for Firms có các khái niệm firm boundary, composite theo mandate/objective/strategy, investment discretion, calculation methodology, GIPS reports và compliance statements. Việc định nghĩa firm phải đầy đủ, có ý nghĩa và không tùy tiện tách bad accounts."},{"id":"S02-03","los_ids":["CFA26-10-04-LOS02"],"heading_vi":"GIPS Standards cấu trúc","body_vi":"2020 edition chia thành standards for firms, asset owners và verifiers. Đối với investment managers, candidates học firms standards về fundamentals of compliance, composites, performance calculations và applicable presentation/disclosure requirements."},{"id":"S02-04","los_ids":["CFA26-10-04-LOS02"],"heading_vi":"Kiểm soát data và audit trail","body_vi":"Compliance không chỉ là lời tuyên bố: cần policies/procedures được ghi nhận, return histories nhất quán, defined composites và controls để giải thích variation. Nếu records không thể đối chiếu, investor không thể đánh giá track record công bằng."},{"id":"S03-01","los_ids":["CFA26-10-04-LOS03"],"heading_vi":"Composite là gì","body_vi":"Composite nhóm các portfolios có investment mandate, objective hoặc strategy tương tự, để báo cáo kết quả đại diện cho năng lực manager với chiến lược đó. Không thể chỉ chọn một winning portfolio để đại diện chiến lược nếu có accounts tương đồng bị bỏ ngoài."},{"id":"S03-02","los_ids":["CFA26-10-04-LOS03"],"heading_vi":"Full inclusion of discretionary portfolios","body_vi":"Đối với GIPS Standards for Firms, phải đưa tất cả actual fee-paying discretionary portfolios phù hợp composite definition vào composite theo yêu cầu. Portfolios không discretionary không được gán vào discretionary composite bất chấp rules, và không được loại losers chỉ vì return thấp."},{"id":"S03-03","los_ids":["CFA26-10-04-LOS03"],"heading_vi":"Tại sao cần composite","body_vi":"Khách hàng đánh giá một manager sẽ áp dụng mandate gần với portfolio của mình; composite giảm survivor bias, cherry-picking và tăng representativeness. Performance khác nhau giữa accounts do cash flows, timing, mandate vẫn phải được xem xét bằng policies."},{"id":"S03-04","los_ids":["CFA26-10-04-LOS03"],"heading_vi":"Benchmark và mục tiêu","body_vi":"Benchmark nên phản ánh opportunity set và strategy được báo cáo; dùng benchmark không phù hợp có thể đánh lừa relative performance. Composite không bảo đảm tất cả accounts cùng return hoặc risk, nhưng cần criteria rõ, consistency và records."},{"id":"S04-01","los_ids":["CFA26-10-04-LOS04"],"heading_vi":"Firm-wide compliance","body_vi":"Để claim GIPS compliance, firm cần đáp ứng toàn bộ applicable requirements; firms là bên chịu trách nhiệm chính với claim và duy trì compliance qua các periods. Không dùng việc verification chưa thực hiện làm lý do bỏ các requirements."},{"id":"S04-02","los_ids":["CFA26-10-04-LOS04"],"heading_vi":"Định nghĩa firm đầy đủ","body_vi":"Firm nên được định nghĩa theo phạm vi rộng và có ý nghĩa nhất, phản ánh hoạt động quản lý thực. Việc cố tách nhóm assets/poor performers ra khỏi definition để làm số đẹp có thể vi phạm spirit fair representation và GIPS requirements."},{"id":"S04-03","los_ids":["CFA26-10-04-LOS04"],"heading_vi":"Định nghĩa investment discretion","body_vi":"Discretion thể hiện manager có authority để thực hiện strategy đã công bố. Nếu khách áp constraints đáng kể ngăn manager áp dụng intended strategy, có thể không còn discretion cho mục tiêu composite; cần documented criteria, không thay đổi tùy lợi nhuận."},{"id":"S04-04","los_ids":["CFA26-10-04-LOS04"],"heading_vi":"Các thông lệ compliance cơ bản","body_vi":"Establish/maintain policies, composite definitions, data capture, return calculations, record retention, presentations và disclosures theo tiêu chuẩn hiện hành. Các claims phải chính xác, không sử dụng phrasing làm khách hàng nghĩ một cá nhân/portfolio được CFA Institute “chứng nhận”."},{"id":"S04-05","los_ids":["CFA26-10-04-LOS04"],"heading_vi":"Recommendations và requirements không đồng nhất","body_vi":"Một số GIPS provisions là bắt buộc, một số là recommendations. Học viên phải nhận diện loại yêu cầu và chỉ claim compliance khi đáp ứng mọi requirements phù hợp. Verification được khuyến khích nhưng không phải điều kiện bắt buộc để tự claim."},{"id":"S05-01","los_ids":["CFA26-10-04-LOS05"],"heading_vi":"Verification là gì","body_vi":"Independent verification là engagement kiểm tra liệu firm/asset owner claiming compliance được thiết kế policies/procedures để comply với GIPS requirements trên phạm vi phù hợp và có triển khai composite maintenance/calculation/presentation processes như quy định. Đây là đánh giá độc lập ở cấp firm, không phải bảo đảm mọi portfolio luôn có return đúng trong mọi tình huống."},{"id":"S05-02","los_ids":["CFA26-10-04-LOS05"],"heading_vi":"Verification không bắt buộc để claim","body_vi":"GIPS khuyến khích independent verification nhằm tăng credibility, nhưng firms có thể tự claim compliance khi đã đáp ứng requirements; verification không phải điều kiện cần bắt buộc. Nói “CFA Institute verified manager” cũng có nguy cơ gây hiểu nhầm, cần mô tả vai trò external verifier chính xác."},{"id":"S05-03","los_ids":["CFA26-10-04-LOS05"],"heading_vi":"Verification so với performance examination","body_vi":"Verification kiểm tra policies/procedures compliance ở firm level. Performance examination là engagement riêng đối với một composite report cụ thể; không được lấy independent verification để khẳng định mọi return của mọi composite đều chính xác."},{"id":"S05-04","los_ids":["CFA26-10-04-LOS05"],"heading_vi":"Limits và decision-making","body_vi":"Verification tăng confidence với data controls và claims, nhưng investor vẫn phải đánh giá objectives, strategy, risk exposure, fees và manager capability. Nó không dự báo alpha hay loại bỏ fraudulent conduct ngoài scope kiểm tra."}],"formulae":[{"id":"F01-01","los_ids":["CFA26-10-04-LOS01"],"expression":"GIPS compliance review = firm scope + applicable requirements + composite eligibility + data controls + disclosure + verification scope","variables":["Descriptive framework only; not a mathematical formula prescribed by CFA Institute."],"assumptions":["Every decision depends on specific case facts and applicable requirements."]},{"id":"F02-01","los_ids":["CFA26-10-04-LOS02"],"expression":"GIPS compliance review = firm scope + applicable requirements + composite eligibility + data controls + disclosure + verification scope","variables":["Descriptive framework only; not a mathematical formula prescribed by CFA Institute."],"assumptions":["Every decision depends on specific case facts and applicable requirements."]},{"id":"F03-01","los_ids":["CFA26-10-04-LOS03"],"expression":"GIPS compliance review = firm scope + applicable requirements + composite eligibility + data controls + disclosure + verification scope","variables":["Descriptive framework only; not a mathematical formula prescribed by CFA Institute."],"assumptions":["Every decision depends on specific case facts and applicable requirements."]},{"id":"F04-01","los_ids":["CFA26-10-04-LOS04"],"expression":"GIPS compliance review = firm scope + applicable requirements + composite eligibility + data controls + disclosure + verification scope","variables":["Descriptive framework only; not a mathematical formula prescribed by CFA Institute."],"assumptions":["Every decision depends on specific case facts and applicable requirements."]},{"id":"F05-01","los_ids":["CFA26-10-04-LOS05"],"expression":"GIPS compliance review = firm scope + applicable requirements + composite eligibility + data controls + disclosure + verification scope","variables":["Descriptive framework only; not a mathematical formula prescribed by CFA Institute."],"assumptions":["Every decision depends on specific case facts and applicable requirements."]}],"worked_examples":[{"id":"E01-01","los_ids":["CFA26-10-04-LOS01"],"problem":"Firm trình bày performance của đúng tài khoản lợi nhuận cao nhất và bỏ các account lỗ.","solution_steps":["Cherry-picking làm méo thành tích tiêu biểu và khả năng so sánh.","GIPS hướng tới performance của toàn bộ composite phù hợp mandate chứ không chỉ winner."],"answer":"Cần group portfolios thích hợp, chuẩn hóa reporting và include terminated accounts theo quy định."},{"id":"E01-02","los_ids":["CFA26-10-04-LOS01"],"problem":"Firm đang xin new institutional mandates và muốn claim một composite tuân thủ GIPS dù các portfolio khác không.","solution_steps":["GIPS claim là ở firm level khi đáp ứng các requirements áp dụng.","Cần evaluate firm-wide adoption/compliance, không gắn claim lên một account tùy ý."],"answer":"Single composite không thay claim tuân thủ của toàn công ty."},{"id":"E02-01","los_ids":["CFA26-10-04-LOS02"],"problem":"Investment manager muốn báo cáo gross return 12% nhưng không nói phí management làm net return 9%.","solution_steps":["Khách hàng phải hiểu basis gross/net, fees và disclosures trọng yếu.","Báo cáo chỉ một số gây hiểu nhầm về kết quả thực nhận."],"answer":"GIPS chú trọng consistency và fair disclosure, không dùng gross-only headline để né thông tin phí."},{"id":"E02-02","los_ids":["CFA26-10-04-LOS02"],"problem":"Firm tự tạo nhóm Global Equity chỉ gồm accounts thắng trong năm hiện tại.","solution_steps":["Composite được định nghĩa theo mandate/objective/strategy, không theo result chọn lọc sau sự kiện.","Đưa tất cả accounts đáp ứng criteria theo requirements và documentation."],"answer":"Group theo performance thực tế là cherry-picking, khác grouping theo investment mandate."},{"id":"E03-01","los_ids":["CFA26-10-04-LOS03"],"problem":"Firm quản lý bốn discretionary Global Equity accounts, returns 12%, 9%, -3%, 5%, manager muốn composite chỉ gồm hai account đầu.","solution_steps":["Cùng mandate và đáp ứng composite criteria thì cần include theo GIPS requirements.","Việc loại account -3% vì kết quả thấp làm composite unrepresentative."],"answer":"Dựng composite theo strategy trước khi biết performance, không chọn winner ex post."},{"id":"E03-02","los_ids":["CFA26-10-04-LOS03"],"problem":"Một portfolio bị client kiểm soát từng trade nên manager không có discretion.","solution_steps":["Không được tự động xem portfolio này là discretionary theo defined strategy.","Xác định authority thực sự, document definition of discretion và composite eligibility."],"answer":"Investment discretion là tiêu chí quan trọng để xác định portfolio membership hợp lệ."},{"id":"E04-01","los_ids":["CFA26-10-04-LOS04"],"problem":"Firm A chia thành hai “firms” trên báo cáo, một nhóm tốt, một nhóm lỗ, dù quản trị chung.","solution_steps":["Đánh giá firm definition có quá hẹp, gây hiểu nhầm khả năng và track record hay không.","GIPS khuyến khích định nghĩa broad và meaningful, cùng policy liên tục."],"answer":"Không dùng định nghĩa firm để lọc kém performance."},{"id":"E04-02","los_ids":["CFA26-10-04-LOS04"],"problem":"Client hạn chế 90% cổ phiếu trong equity mandate, manager không thể thực thi strategy.","solution_steps":["Cần đánh giá portfolio còn discretionary theo tiêu chí xác định trước hay không.","Không giả định mọi account có asset-management agreement đều discretionary."],"answer":"Investment discretion phải được định nghĩa có bằng chứng và nhất quán."},{"id":"E05-01","los_ids":["CFA26-10-04-LOS05"],"problem":"Manager mới tuân thủ GIPS đúng quy định nhưng chưa thuê verifier.","solution_steps":["Independent verification được khuyến khích, không bắt buộc để claim compliance.","Firm vẫn cần documentary evidence và đáp ứng mọi requirements."],"answer":"Không có verifier không tự động là non-compliance, cũng không là bằng chứng compliance."},{"id":"E05-02","los_ids":["CFA26-10-04-LOS05"],"problem":"Asset manager đã được verified firm-wide, nên sales nói “mọi portfolio return được kiểm toán và CFA đảm bảo”.","solution_steps":["Verification không bảo đảm từng return/composite; đây là misleading exaggeration.","Chỉ công bố scope verification và tách performance examination nếu thực hiện."],"answer":"Phân biệt verification firm-level với assurance đối với composite performance."}],"questions":[{"id":"Q01-01","los_ids":["CFA26-10-04-LOS01"],"stem":"GIPS có mục tiêu chính?","options":["Bảo đảm lợi nhuận dương","Tăng comparability và fair presentation","Loại bỏ mọi systematic risk"],"correct_option":1,"explanation":"GIPS xây dựng chuẩn thống nhất nhằm hạn chế cherry-picking và improving fair reporting, chứ không bảo đảm positive returns."},{"id":"Q01-02","los_ids":["CFA26-10-04-LOS01"],"stem":"Đơn vị nào có thể claim GIPS compliance for firms?","options":["Một portfolio riêng bất kỳ","Một benchmark index","Firm đáp ứng toàn bộ requirements liên quan"],"correct_option":2,"explanation":"Compliance claim theo GIPS Standards for Firms áp dụng cho firm as defined; single portfolio/composite không tự claim độc lập."},{"id":"Q01-03","los_ids":["CFA26-10-04-LOS01"],"stem":"Tài liệu GIPS có bắt buộc verification để được claim?","options":["Không, verification được khuyến khích nhưng không phải điều kiện cần","Có, mọi firms phải verification trước","Chỉ cần audit một tài khoản winner"],"correct_option":0,"explanation":"Firms có thể claim compliance tự thân khi đáp ứng requirements; independent verification không phải điều kiện bắt buộc của compliance claim."},{"id":"Q02-01","los_ids":["CFA26-10-04-LOS02"],"stem":"Nguyên tắc cốt lõi GIPS là?","options":["Mỗi portfolio đều cần cùng return","Fair representation và full disclosure","Loại bỏ nhu cầu data kiểm tra"],"correct_option":1,"explanation":"GIPS bảo vệ tính so sánh của track record bằng chuẩn methodology, fair reporting và disclosures."},{"id":"Q02-02","los_ids":["CFA26-10-04-LOS02"],"stem":"GIPS Standard for Firms cần kiểm soát?","options":["Chỉ tên một account winner","Chỉ doanh thu bán hàng","Firm definition, composites và data policies"],"correct_option":2,"explanation":"Firm-wide consistency, composite membership và tính chính xác của performance data là các thành phần thiết yếu."},{"id":"Q02-03","los_ids":["CFA26-10-04-LOS02"],"stem":"GIPS 2020 gồm?","options":["Standards for firms, asset owners và verifiers","Chỉ một handbook portfolio","Chỉ luật niêm yết"],"correct_option":0,"explanation":"2020 edition phân biệt đối tượng firms, asset owners và verification providers."},{"id":"Q03-01","los_ids":["CFA26-10-04-LOS03"],"stem":"Composite grouping chủ yếu dựa trên?","options":["Lợi nhuận 3 tháng tốt nhất","Cùng mandate/objective/strategy","Tên khách hàng cùng quốc tịch"],"correct_option":1,"explanation":"Grouping cần investment mandate, objective hoặc strategy tương đồng, không phải mức lãi đã quan sát."},{"id":"Q03-02","los_ids":["CFA26-10-04-LOS03"],"stem":"GIPS discretionary composite phù hợp sẽ bao gồm?","options":["Chỉ profitable portfolios","Chỉ largest portfolios","Tất cả actual fee-paying discretionary portfolios phù hợp criteria"],"correct_option":2,"explanation":"Full appropriate inclusion nhằm tránh selection bias, chứ không chỉ chọn winner accounts."},{"id":"Q03-03","los_ids":["CFA26-10-04-LOS03"],"stem":"Một composite có tài khoản lỗ có nên xóa để nâng return?","options":["Không; cherry-picking là trái fair representation","Có nếu đã lập report xong","Có nếu khách hàng không hỏi"],"correct_option":0,"explanation":"Các portfolios đáp ứng tiêu chí membership không thể bị bỏ chỉ vì performance xấu."},{"id":"Q04-01","los_ids":["CFA26-10-04-LOS04"],"stem":"GIPS yêu cầu firm definition thường theo hướng?","options":["Tách tất cả accounts lỗ","Rộng và có ý nghĩa","Chỉ accounts cao nhất"],"correct_option":1,"explanation":"Firm boundary được định nghĩa đầy đủ và có ý nghĩa, không lựa chọn kết quả ex post."},{"id":"Q04-02","los_ids":["CFA26-10-04-LOS04"],"stem":"Discretion có ý nghĩa gì?","options":["Manager bảo đảm return","Chỉ số beta portfolio","Manager có authority thực thi investment strategy"],"correct_option":2,"explanation":"Discretion liên quan quyền quyết định theo mandate, là tiêu chí cho composite membership."},{"id":"Q04-03","los_ids":["CFA26-10-04-LOS04"],"stem":"Điều nào đúng về compliance?","options":["Phải đáp ứng mọi applicable GIPS requirements","Chỉ cần một tài khoản tốt","Được tự nhận kể cả thiếu requirements"],"correct_option":0,"explanation":"GIPS compliance là claim ở firm level dựa trên complete requirements, không phải lựa chọn từng phần theo marketing."},{"id":"Q05-01","los_ids":["CFA26-10-04-LOS05"],"stem":"Verification có phải điều kiện bắt buộc của claim GIPS?","options":["Có, mọi firm phải mua verifier","Không, được khuyến khích nhưng không bắt buộc","Chỉ GIPS portfolio winners cần verification"],"correct_option":1,"explanation":"Verification được khuyến khích; firm tự chịu trách nhiệm compliance claim và phải đáp ứng mọi requirements dù chưa verified."},{"id":"Q05-02","los_ids":["CFA26-10-04-LOS05"],"stem":"Independent verification chủ yếu kiểm tra?","options":["Tương lai mọi portfolio return","Mọi client đều có IRR bằng nhau","Cơ cấu policy/process compliance ở firm level"],"correct_option":2,"explanation":"Verification là firm-level engagement về policies/procedures compliance, khác một audit đảm bảo từng investment outcome."},{"id":"Q05-03","los_ids":["CFA26-10-04-LOS05"],"stem":"Verification và performance examination?","options":["Verification là firm-level, performance examination gắn một composite report","Là cùng một cuộc kiểm tra từng account","GIPS cấm performance examination"],"correct_option":0,"explanation":"Phân biệt scope của firm-wide verification với optional composite-specific performance examination giúp tránh overclaim compliance."}],"flashcards":[{"id":"C01-01","los_ids":["CFA26-10-04-LOS01"],"front":"Mục đích của GIPS — nêu cách xử lý?","back":"GIPS (Global Investment Performance Standards) nhằm thúc đẩy trình bày track record công bằng, minh bạch, nhất quán và có thể so sánh xuyên manager/markets. Trước khi có chuẩn, các cách cherry-picking winner accounts, survivorship bias và thay kỳ báo cáo tùy ý khiến khách hàng khó đánh giá năng lực quản lý thực."},{"id":"C01-02","los_ids":["CFA26-10-04-LOS01"],"front":"Ai có thể claim compliance — nêu cách xử lý?","back":"Các firms quản lý tài sản cạnh tranh để nhận investment management business có thể claim compliance với GIPS Standards for Firms khi đáp ứng mọi applicable requirements. Asset owners có GIPS Standards for Asset Owners riêng. Một portfolio hoặc composite đơn lẻ không tự xưng tuân thủ thay cho cả firm."},{"id":"C01-03","los_ids":["CFA26-10-04-LOS01"],"front":"Lợi ích cho nhà đầu tư và firms — nêu cách xử lý?","back":"Prospective clients có phương pháp so sánh performance rõ hơn; firms có reporting disciplines, data controls và credibility. Standards khuyến khích fair competition nhưng không bảo đảm một manager outperform benchmark hoặc không có risk."},{"id":"C01-04","los_ids":["CFA26-10-04-LOS01"],"front":"Các điều không đúng — nêu cách xử lý?","back":"GIPS nhìn chung không tự động bắt buộc theo luật ở mọi jurisdiction và không phải chứng chỉ do CFA Institute trao cho từng chiến lược. Một firm có thể tự claim tuân thủ nếu thực sự đáp ứng quy định, còn verification là quy trình đánh giá độc lập được khuyến khích."},{"id":"C02-01","los_ids":["CFA26-10-04-LOS02"],"front":"Fair representation và full disclosure — nêu cách xử lý?","back":"GIPS đòi hỏi returns được tính/diễn giải nhất quán, report phù hợp với prescribed methodology và cung cấp disclosures làm rõ assumptions, fees, composites, benchmarks. Không chọn những account và period làm performance trông đẹp hơn."},{"id":"C02-02","los_ids":["CFA26-10-04-LOS02"],"front":"Firm, composite và discretion — nêu cách xử lý?","back":"GIPS Standards for Firms có các khái niệm firm boundary, composite theo mandate/objective/strategy, investment discretion, calculation methodology, GIPS reports và compliance statements. Việc định nghĩa firm phải đầy đủ, có ý nghĩa và không tùy tiện tách bad accounts."},{"id":"C02-03","los_ids":["CFA26-10-04-LOS02"],"front":"GIPS Standards cấu trúc — nêu cách xử lý?","back":"2020 edition chia thành standards for firms, asset owners và verifiers. Đối với investment managers, candidates học firms standards về fundamentals of compliance, composites, performance calculations và applicable presentation/disclosure requirements."},{"id":"C02-04","los_ids":["CFA26-10-04-LOS02"],"front":"Kiểm soát data và audit trail — nêu cách xử lý?","back":"Compliance không chỉ là lời tuyên bố: cần policies/procedures được ghi nhận, return histories nhất quán, defined composites và controls để giải thích variation. Nếu records không thể đối chiếu, investor không thể đánh giá track record công bằng."},{"id":"C03-01","los_ids":["CFA26-10-04-LOS03"],"front":"Composite là gì — nêu cách xử lý?","back":"Composite nhóm các portfolios có investment mandate, objective hoặc strategy tương tự, để báo cáo kết quả đại diện cho năng lực manager với chiến lược đó. Không thể chỉ chọn một winning portfolio để đại diện chiến lược nếu có accounts tương đồng bị bỏ ngoài."},{"id":"C03-02","los_ids":["CFA26-10-04-LOS03"],"front":"Full inclusion of discretionary portfolios — nêu cách xử lý?","back":"Đối với GIPS Standards for Firms, phải đưa tất cả actual fee-paying discretionary portfolios phù hợp composite definition vào composite theo yêu cầu. Portfolios không discretionary không được gán vào discretionary composite bất chấp rules, và không được loại losers chỉ vì return thấp."},{"id":"C03-03","los_ids":["CFA26-10-04-LOS03"],"front":"Tại sao cần composite — nêu cách xử lý?","back":"Khách hàng đánh giá một manager sẽ áp dụng mandate gần với portfolio của mình; composite giảm survivor bias, cherry-picking và tăng representativeness. Performance khác nhau giữa accounts do cash flows, timing, mandate vẫn phải được xem xét bằng policies."},{"id":"C03-04","los_ids":["CFA26-10-04-LOS03"],"front":"Benchmark và mục tiêu — nêu cách xử lý?","back":"Benchmark nên phản ánh opportunity set và strategy được báo cáo; dùng benchmark không phù hợp có thể đánh lừa relative performance. Composite không bảo đảm tất cả accounts cùng return hoặc risk, nhưng cần criteria rõ, consistency và records."},{"id":"C04-01","los_ids":["CFA26-10-04-LOS04"],"front":"Firm-wide compliance — nêu cách xử lý?","back":"Để claim GIPS compliance, firm cần đáp ứng toàn bộ applicable requirements; firms là bên chịu trách nhiệm chính với claim và duy trì compliance qua các periods. Không dùng việc verification chưa thực hiện làm lý do bỏ các requirements."},{"id":"C04-02","los_ids":["CFA26-10-04-LOS04"],"front":"Định nghĩa firm đầy đủ — nêu cách xử lý?","back":"Firm nên được định nghĩa theo phạm vi rộng và có ý nghĩa nhất, phản ánh hoạt động quản lý thực. Việc cố tách nhóm assets/poor performers ra khỏi definition để làm số đẹp có thể vi phạm spirit fair representation và GIPS requirements."},{"id":"C04-03","los_ids":["CFA26-10-04-LOS04"],"front":"Định nghĩa investment discretion — nêu cách xử lý?","back":"Discretion thể hiện manager có authority để thực hiện strategy đã công bố. Nếu khách áp constraints đáng kể ngăn manager áp dụng intended strategy, có thể không còn discretion cho mục tiêu composite; cần documented criteria, không thay đổi tùy lợi nhuận."},{"id":"C04-04","los_ids":["CFA26-10-04-LOS04"],"front":"Các thông lệ compliance cơ bản — nêu cách xử lý?","back":"Establish/maintain policies, composite definitions, data capture, return calculations, record retention, presentations và disclosures theo tiêu chuẩn hiện hành. Các claims phải chính xác, không sử dụng phrasing làm khách hàng nghĩ một cá nhân/portfolio được CFA Institute “chứng nhận”."},{"id":"C04-05","los_ids":["CFA26-10-04-LOS04"],"front":"Recommendations và requirements không đồng nhất — nêu cách xử lý?","back":"Một số GIPS provisions là bắt buộc, một số là recommendations. Học viên phải nhận diện loại yêu cầu và chỉ claim compliance khi đáp ứng mọi requirements phù hợp. Verification được khuyến khích nhưng không phải điều kiện bắt buộc để tự claim."},{"id":"C05-01","los_ids":["CFA26-10-04-LOS05"],"front":"Verification là gì — nêu cách xử lý?","back":"Independent verification là engagement kiểm tra liệu firm/asset owner claiming compliance được thiết kế policies/procedures để comply với GIPS requirements trên phạm vi phù hợp và có triển khai composite maintenance/calculation/presentation processes như quy định. Đây là đánh giá độc lập ở cấp firm, không phải bảo đảm mọi portfolio luôn có return đúng trong mọi tình huống."},{"id":"C05-02","los_ids":["CFA26-10-04-LOS05"],"front":"Verification không bắt buộc để claim — nêu cách xử lý?","back":"GIPS khuyến khích independent verification nhằm tăng credibility, nhưng firms có thể tự claim compliance khi đã đáp ứng requirements; verification không phải điều kiện cần bắt buộc. Nói “CFA Institute verified manager” cũng có nguy cơ gây hiểu nhầm, cần mô tả vai trò external verifier chính xác."},{"id":"C05-03","los_ids":["CFA26-10-04-LOS05"],"front":"Verification so với performance examination — nêu cách xử lý?","back":"Verification kiểm tra policies/procedures compliance ở firm level. Performance examination là engagement riêng đối với một composite report cụ thể; không được lấy independent verification để khẳng định mọi return của mọi composite đều chính xác."},{"id":"C05-04","los_ids":["CFA26-10-04-LOS05"],"front":"Limits và decision-making — nêu cách xử lý?","back":"Verification tăng confidence với data controls và claims, nhưng investor vẫn phải đánh giá objectives, strategy, risk exposure, fees và manager capability. Nó không dự báo alpha hay loại bỏ fraudulent conduct ngoài scope kiểm tra."}],"review_status":"targeted_los_source_scenario_and_browser_QA_pass_not_exhaustive_all_PDFs"}]);
window.CFA_AUDIT_TOTALS=(function(previous){previous=previous||{};return {...previous,drafted:Math.max(Number(previous.drafted)||0,363),independently_reaudited:Math.max(Number(previous.independently_reaudited)||0,220),scope:"Targeted source review of LOS, not exhaustive all uploaded PDFs"};})(window.CFA_AUDIT_TOTALS);
